type PrivateIntakeMode = "redress" | "distress" | "workload" | "connection" | "conflict" | "selfview" | "general";
type PrivateIntakeFieldKey = keyof PrivateIntakeDraft;
type PrivateIntakeQuestion = {
  field: PrivateIntakeFieldKey;
  label: string;
  placeholder: string;
  meta: string;
  multiline?: boolean;
};
type PrivateIntakeSection = {
  id: string;
  title: string;
  meta: string;
  intro: string;
  questions: PrivateIntakeQuestion[];
};
type PrivateIntakeBlueprint = {
  mode: PrivateIntakeMode;
  modeLabel: string;
  modeSummary: string;
  analysisLenses: string[];
  flowSteps: Array<{ id: string; title: string; meta: string }>;
  sections: PrivateIntakeSection[];
  sourcePack: Array<{ title: string; detail: string; url: string | null }>;
};

function buildPrivateIntakeQuestion(
  field: PrivateIntakeFieldKey,
  label: string,
  placeholder: string,
  meta: string,
  multiline = false
): PrivateIntakeQuestion {
  return { field, label, placeholder, meta, multiline };
}

function getPrivateIntakeMode(issueId: IssueId, routeTab: "guide" | "redress"): PrivateIntakeMode {
  if (routeTab === "redress") return "redress";
  // Conflict: interpersonal tension and repair
  if (issueId === "anger" || issueId === "relationship") return "conflict";
  // Distress: emotional overwhelm, fear, health anxiety, trauma, addiction triggers
  if (issueId === "anxiety" || issueId === "fear" || issueId === "stigma" || issueId === "trauma" || issueId === "addiction" || issueId === "health") return "distress";
  // Workload: practical pressure overload
  if (issueId === "burnout" || issueId === "financial" || issueId === "parenting" || issueId === "academic") return "workload";
  // Connection: loss, isolation, needing witness/support
  if (issueId === "loneliness" || issueId === "grief") return "connection";
  // Self-view: self-perception, identity examination
  if (issueId === "overconfidence" || issueId === "identity") return "selfview";
  return "general";
}

