function countPrivateIntakeFields(draft: PrivateIntakeDraft) {
  return Object.values(draft).reduce((count, value) => (value.trim().length > 0 ? count + 1 : count), 0);
}

function buildPrivateIntakeReport(
  draft: PrivateIntakeDraft,
  selectedIdentityLabel: string,
  selectedIssueGuide: IssueGuide,
  routeTab: "guide" | "redress"
) {
  const blueprint = getPrivateIntakeBlueprint(selectedIssueGuide.id, selectedIdentityLabel, routeTab);
  const filledCount = countPrivateIntakeFields(draft);
  const totalCount = Object.keys(draft).length;
  const coverage = `${filledCount}/${totalCount}`;
  const normalizedText = Object.values(draft)
    .map((value) => value.trim().toLowerCase())
    .join(" ");
  const hasSafetyCue =
    isUrgentSafetySignal(normalizedText) || draft.safetyNote.trim().length > 0;
  const emotionalHigh =
    /(overwhelming|panic|panic attack|very high|severe|can'?t cope|cannot cope|terrified|hopeless|ashamed|numb|breakdown)/.test(
      `${draft.currentFeeling} ${draft.emotionIntensity} ${draft.triggerContext} ${draft.bodySignal}`.toLowerCase()
    );
  const practicalHigh =
    /(work|school|college|exam|money|sleep|food|job|office|deadline|duty|family|home|health|care|rent|loan|travel)/.test(
      `${draft.overview} ${draft.timelineContext} ${draft.frequencyContext} ${draft.dailyImpactContext} ${draft.previousAttempts} ${draft.neededOutcome}`.toLowerCase()
    );
  const socialHigh =
    /(family|relative|friend|friends|coworker|boss|teacher|student|parent|child|group|team)/.test(
      `${draft.familyContext} ${draft.relativeContext} ${draft.friendsContext} ${draft.coworkerContext}`.toLowerCase()
    );
  const supportHigh =
    /(need|help|support|listen|calm|guidance|advice|doctor|counselor|lawyer|complaint|action)/.test(
      `${draft.supportNeed} ${draft.supportPreferences} ${draft.neededOutcome}`.toLowerCase()
    );
  const recommendedRoute = hasSafetyCue
    ? "SOS / Help"
    : emotionalHigh
      ? "Reset"
      : practicalHigh
        ? "Path"
        : supportHigh
          ? "Guidance"
          : "Explore";
  const emotionalRead = emotionalHigh
    ? "The emotional load looks high and deserves a calm, slower first step."
    : draft.currentFeeling.trim().length > 0
      ? "The emotional side is visible and can be guided with a cleaner route."
      : "The emotional picture still needs a little more detail.";
  const practicalRead = practicalHigh
    ? "The practical side is active: the issue is touching time, work, study, home, money, or routine."
    : draft.dailyImpactContext.trim().length > 0 || draft.previousAttempts.trim().length > 0
      ? "There is enough practical context to shape a next action."
      : "The practical impact still needs a few more concrete details.";
  const socialRead = socialHigh
    ? "The people layer is important here, so the app should keep family, friends, or coworkers in view."
    : draft.familyContext.trim().length > 0 ||
        draft.relativeContext.trim().length > 0 ||
        draft.friendsContext.trim().length > 0 ||
        draft.coworkerContext.trim().length > 0
      ? "The people layer is present, even if the pressure is still being filled in."
      : "The people layer is not yet fully described.";
  const safetyRead = hasSafetyCue
    ? "A safety note is present, so the route should keep urgent help visible."
    : "No urgent safety cue is visible in the intake so far.";

  const modeLabel = blueprint.modeLabel;
  const summary = `${selectedIdentityLabel} / ${selectedIssueGuide.label}. This ${modeLabel.toLowerCase()} intake changes with the situation, uses your answers, and leans on verified reference pages chosen for this route.`;
  const reportBasis = `Question set: ${modeLabel}. Evidence style: ${
    routeTab === "redress" ? "official grievance and safety sources" : "official mental-health and coping sources"
  }.`;
  const nextStep = hasSafetyCue
    ? "Open SOS or Help first, then keep the complaint or support path visible."
    : routeTab === "redress" || blueprint.mode === "redress"
      ? "Open Help first, then keep the complaint route and evidence together."
      : emotionalHigh
        ? "Open Reset first, then move to Path once the body feels steadier."
        : practicalHigh
          ? "Open Path first, then move to Help if you need a complaint or authority route."
          : "Open Guidance for one clean next step, then continue from there.";

  return {
    coverage,
    emotionalLabel: emotionalHigh ? "High" : draft.currentFeeling.trim().length > 0 ? "Present" : "Light",
    practicalLabel: practicalHigh ? "High" : draft.dailyImpactContext.trim().length > 0 ? "Present" : "Light",
    socialLabel: socialHigh ? "Strong" : draft.familyContext.trim().length > 0 ? "Present" : "Light",
    safetyLabel: hasSafetyCue ? "Urgent" : "Clear",
    emotionalRead,
    practicalRead,
    socialRead,
    safetyRead,
    recommendedRoute,
    summary,
    reportBasis,
    analysisLenses: blueprint.analysisLenses,
    nextStep,
    modeLabel,
    safetyVisible: hasSafetyCue,
    sourcePack: blueprint.sourcePack
  };
}

function buildStepVisitReport(
  entry: CheckInEntry,
  selectedIdentityLabel: string,
  selectedIssueGuide: IssueGuide,
  routePreview: RoutePreview,
  weeklyAverage: number,
  context: {
    languageLabel: string;
    verificationLabel: string;
    intakeCoverage: string;
    intakeModeLabel: string;
  }
): VisitReport {
  const clarityLabel =
    entry.score >= 76 ? "steady" : entry.score >= 58 ? "growing" : entry.score >= 40 ? "fragile" : "under strain";

  return {
    id: `step-${entry.id}`,
    createdAt: entry.createdAt,
    kind: "step",
    title: `Step report / ${formatDateTime(entry.createdAt)}`,
    summary: `${selectedIdentityLabel} logged a ${clarityLabel} step. ${routePreview.detail}`,
    emotional: `Tone ${entry.toneLabel} and clarity ${entry.score}/100.`,
    practical: `Routine ${entry.routineName}. Weekly average ${weeklyAverage}.`,
    social: `Issue focus: ${selectedIssueGuide.label}.`,
    safety: "Use SOS or Help if anything shifts from heavy to unsafe.",
    nextStep: selectedIssueGuide.steps[0],
    routeLabel: routePreview.title,
    identityLabel: selectedIdentityLabel,
    issueLabel: selectedIssueGuide.label,
    entryCount: 1,
    sourceLabel: "Saved check-in",
    reportBasis: `Issue lens: ${selectedIssueGuide.logicalLens}`,
    analysisLenses: [selectedIssueGuide.logicalLens, selectedIssueGuide.theoreticalLens],
    dataTrail: [
      `Profile: ${selectedIdentityLabel}`,
      `Language: ${context.languageLabel}`,
      `Verification: ${context.verificationLabel}`,
      `Intake: ${context.intakeModeLabel} / ${context.intakeCoverage}`,
      `Routine: ${entry.routineName}`,
      `Route: ${routePreview.title}`
    ]
  };
}

function buildDailyVisitReport(
  todayEntries: CheckInEntry[],
  privateIntakeReport: ReturnType<typeof buildPrivateIntakeReport>,
  selectedIdentityLabel: string,
  selectedIssueGuide: IssueGuide,
  routePreview: RoutePreview,
  dailyRoutinePlan: DailyRoutinePlan,
  weeklyAverage: number,
  monthlyAverage: number,
  context: {
    languageLabel: string;
    verificationLabel: string;
    intakeCoverage: string;
    intakeModeLabel: string;
  }
): VisitReport {
  const latestEntry = todayEntries[0] ?? null;
  const entryCount = todayEntries.length;
  const averageScore =
    entryCount > 0
      ? Math.round(todayEntries.reduce((sum, entry) => sum + entry.score, 0) / entryCount)
      : 0;
  const reportTone =
    averageScore >= 76 ? "steady" : averageScore >= 58 ? "mixed but improving" : averageScore >= 40 ? "fragile" : "heavy";

  return {
    id: `daily-${Date.now()}`,
    createdAt: new Date().toISOString(),
    kind: "daily",
    title: `Daily report / ${formatDate(new Date().toISOString())}`,
    summary:
      entryCount > 0
        ? `Today had ${entryCount} saved step${entryCount === 1 ? "" : "s"} and a ${reportTone} overall tone. ${routePreview.title} stays the next clean route. Intake basis: ${privateIntakeReport.modeLabel} / ${context.intakeCoverage}.`
        : `No step was saved yet today, so this report is built from the guided intake and the current route. ${routePreview.title} stays ready for the next action. Intake basis: ${privateIntakeReport.modeLabel} / ${context.intakeCoverage}.`,
    emotional:
      latestEntry !== null
        ? `Latest check-in: ${latestEntry.toneLabel} / ${latestEntry.score}.`
        : privateIntakeReport.emotionalRead,
    practical:
      entryCount > 0
        ? `Routine coverage: ${dailyRoutinePlan.actions
              .filter(
              (action) =>
                action.kind === "save" ||
                action.kind === "guide" ||
                action.kind === "play" ||
                action.kind === "focus" ||
                action.kind === "journal"
            )
            .map((action) => action.label)
            .join(" · ")}. Weekly average ${weeklyAverage}, monthly average ${monthlyAverage}.`
        : privateIntakeReport.practicalRead,
    social: privateIntakeReport.socialRead,
    safety: privateIntakeReport.safetyRead,
    nextStep:
      entryCount > 0
        ? `${selectedIssueGuide.steps[0]} Then return to ${routePreview.title}.`
        : privateIntakeReport.nextStep,
    routeLabel: routePreview.title,
    identityLabel: selectedIdentityLabel,
    issueLabel: selectedIssueGuide.label,
    entryCount,
    sourceLabel: entryCount > 0 ? "Today’s saved steps" : "Guided intake",
    reportBasis: privateIntakeReport.reportBasis,
    analysisLenses: privateIntakeReport.analysisLenses,
    dataTrail: [
      `Profile: ${selectedIdentityLabel}`,
      `Language: ${context.languageLabel}`,
      `Verification: ${context.verificationLabel}`,
      `Intake: ${context.intakeModeLabel} / ${context.intakeCoverage}`,
      `Routine loop: ${dailyRoutinePlan.summary}`,
      `Weekly / monthly: ${weeklyAverage} / ${monthlyAverage}`
    ]
  };
}

function normalizeVisitReport(value: unknown): VisitReport | null {
  if (!value || typeof value !== "object") return null;
  const report = value as Partial<VisitReport>;
  const kind = report.kind === "step" || report.kind === "daily" ? report.kind : "step";
  return {
    id:
      typeof report.id === "string" && report.id.trim().length > 0
        ? report.id
        : `visit-${Date.now()}-${Math.floor(Math.random() * 10000)}`,
    createdAt:
      typeof report.createdAt === "string" && report.createdAt.trim().length > 0
        ? report.createdAt
        : new Date().toISOString(),
    kind,
    title: typeof report.title === "string" ? report.title : "",
    summary: typeof report.summary === "string" ? report.summary : "",
    emotional: typeof report.emotional === "string" ? report.emotional : "",
    practical: typeof report.practical === "string" ? report.practical : "",
    social: typeof report.social === "string" ? report.social : "",
    safety: typeof report.safety === "string" ? report.safety : "",
    nextStep: typeof report.nextStep === "string" ? report.nextStep : "",
    routeLabel: typeof report.routeLabel === "string" ? report.routeLabel : "",
    identityLabel: typeof report.identityLabel === "string" ? report.identityLabel : "",
    issueLabel: typeof report.issueLabel === "string" ? report.issueLabel : "",
    entryCount:
      typeof report.entryCount === "number" && Number.isFinite(report.entryCount)
        ? Math.max(0, Math.floor(report.entryCount))
        : 0,
    sourceLabel: typeof report.sourceLabel === "string" ? report.sourceLabel : "",
    reportBasis: typeof report.reportBasis === "string" ? report.reportBasis : undefined,
    analysisLenses: Array.isArray(report.analysisLenses)
      ? report.analysisLenses.filter((item): item is string => typeof item === "string" && item.trim().length > 0)
      : undefined,
    dataTrail: Array.isArray(report.dataTrail)
      ? report.dataTrail.filter((item): item is string => typeof item === "string" && item.trim().length > 0)
      : undefined
  };
}

function normalizeVisitReports(value: unknown): VisitReport[] {
  if (!Array.isArray(value)) return [];
  return value.map(normalizeVisitReport).filter((report): report is VisitReport => report !== null).slice(0, 40);
}

