type PracticeRoleFrame = {
  shortLabel: string;
  note: string;
  resetContext: string;
  focusTask: string;
  focusDistraction: string;
  moveContext: string;
  connectPerson: string;
  reflectContext: string;
};

function getPracticeRoleFrame(identityId: IdentityId): PracticeRoleFrame {
  if (identityId === "student" || identityId === "child") {
    return {
      shortLabel: identityId === "student" ? "Student version" : "Student version",
      note: "Keep it tied to class, notes, sleep, and one clean win.",
      resetContext: "the next class or study block",
      focusTask: identityId === "student" ? "study task" : "homework or revision task",
      focusDistraction: "worry, noise, or one distracting app",
      moveContext: "a desk break or short walk between lessons",
      connectPerson: identityId === "student" ? "classmate, mentor, or parent" : "trusted adult or safe family member",
      reflectContext: identityId === "student" ? "the assignment or class that felt heavy" : "the school moment or feeling that felt too big"
    };
  }

  if (identityId === "teacher") {
    return {
      shortLabel: "Teacher version",
      note: "Keep it tied to class transitions, planning, and one quiet reset between people.",
      resetContext: "the next lesson handoff",
      focusTask: "lesson prep or marking task",
      focusDistraction: "the next interruption or open loop",
      moveContext: "a short pause between classes",
      connectPerson: "colleague, coordinator, or friend",
      reflectContext: "the last classroom moment or meeting"
    };
  }

  if (identityId === "doctor" || identityId === "nurse") {
    return {
      shortLabel: "Shift version",
      note: "Keep it tied to handovers, hydration, and one clear care task.",
      resetContext: "the next handover or patient block",
      focusTask: "clinical note or care task",
      focusDistraction: "a noisy thought loop or extra tab",
      moveContext: "the end of the shift or a short corridor walk",
      connectPerson: "trusted colleague or family member",
      reflectContext: "the last care decision or shift moment"
    };
  }

  if (identityId === "officer" || identityId === "official") {
    return {
      shortLabel: "Duty version",
      note: "Keep it tied to debriefs, duty, privacy, and clear handovers.",
      resetContext: "the next duty block or handoff",
      focusTask: "report, note, or follow-up task",
      focusDistraction: "a reaction you do not need to send yet",
      moveContext: "a short reset after duty or before the next call",
      connectPerson: "trusted colleague, senior, or family member",
      reflectContext: "the last duty decision or situation"
    };
  }

  if (
    identityId === "banker" ||
    identityId === "engineer" ||
    identityId === "lawyer" ||
    identityId === "professional" ||
    identityId === "entrepreneur"
  ) {
    return {
      shortLabel: "Work version",
      note: "Keep it tied to one work block, one decision, and fewer open loops.",
      resetContext: "the next work block",
      focusTask: "work task or decision block",
      focusDistraction: "one noisy tab or extra demand",
      moveContext: "a short break between calls or screens",
      connectPerson: "colleague, mentor, or trusted friend",
      reflectContext: "the work moment or decision that felt heavy"
    };
  }

  if (identityId === "parent" || identityId === "caregiver" || identityId === "homemaker") {
    return {
      shortLabel: "Care version",
      note: "Keep it tied to family care, a handoff, and one small pause for you too.",
      resetContext: "the next family task or handoff",
      focusTask: "home task or care task",
      focusDistraction: "one extra demand that is not urgent",
      moveContext: "a short stretch between care moments",
      connectPerson: "partner, family member, or trusted helper",
      reflectContext: "the home moment or care load that felt heavy"
    };
  }

  if (identityId === "retired") {
    return {
      shortLabel: "Retired version",
      note: "Keep it tied to routine, movement, and a calm pace.",
      resetContext: "the next calm moment in the day",
      focusTask: "small routine task",
      focusDistraction: "one unnecessary worry or task",
      moveContext: "your next walk or stretch",
      connectPerson: "friend, relative, or neighbour",
      reflectContext: "the part of the day that felt crowded"
    };
  }

  return {
    shortLabel: "General version",
    note: "Keep it small, practical, and easy to finish.",
    resetContext: "the next calm moment",
    focusTask: "useful task",
    focusDistraction: "one distraction that steals attention",
    moveContext: "a short pause in the day",
    connectPerson: "trusted person",
    reflectContext: "the moment that felt heavy"
  };
}

function getIssuePracticeTone(issueId: IssueId) {
  if (issueId === "general") {
    return {
      issueLabel: "general guidance",
      reset: "Start neutral and slow the flow before naming the issue too soon.",
      focus: "Choose one route, one step, and one follow-up.",
      move: "Small movement can keep the page from overcommitting to the wrong label.",
      connect: "A steady second opinion helps when the problem is still being sorted.",
      reflect: "Write the facts first, then name the issue only if it stays clear."
    };
  }

  if (issueId === "anxiety") {
    return {
      issueLabel: "anxiety",
      reset: "Lower the body load before the worry decides the pace.",
      focus: "Use a smaller task and a shorter timer than your worry wants.",
      move: "Let movement drain the tension instead of holding it in place.",
      connect: "One safe contact is better than staying alone with the spiral.",
      reflect: "Write the fear plainly, then write the fact next to it."
    };
  }

  if (issueId === "burnout") {
    return {
      issueLabel: "burnout",
      reset: "Protect recovery first; output can wait a little.",
      focus: "Choose one task that is genuinely small and closeable.",
      move: "Move enough to reduce strain, not enough to perform.",
      connect: "Ask for support before the load becomes another wall.",
      reflect: "Name what is draining you, not just what is unfinished."
    };
  }

  if (issueId === "loneliness") {
    return {
      issueLabel: "loneliness",
      reset: "A calm body makes reaching out less hard.",
      focus: "Use a task that leaves room for one real connection.",
      move: "Movement can soften the isolation before you text or call.",
      connect: "One human touchpoint matters more than a perfect plan.",
      reflect: "Write what kind of contact would actually help today."
    };
  }

  if (issueId === "anger") {
    return {
      issueLabel: "anger",
      reset: "Cool the heat before it becomes a message or decision.",
      focus: "Pick a task that keeps the reply out of the draft box for now.",
      move: "Use movement to lower pressure before you speak.",
      connect: "A trusted person can help keep the reply clean.",
      reflect: "Write the trigger first and the clean response second."
    };
  }

  if (issueId === "overconfidence") {
    return {
      issueLabel: "overconfidence",
      reset: "Slow down enough to see the missing check.",
      focus: "Pick a task that includes one review, not just one move.",
      move: "Movement helps the body drop the rush.",
      connect: "Ask for one honest check before you act too fast.",
      reflect: "Write what could be missed if you move on instinct alone."
    };
  }

  if (issueId === "stigma") {
    return {
      issueLabel: "stigma",
      reset: "Lower shame before you try to solve the problem.",
      focus: "Choose a task that protects privacy and keeps dignity intact.",
      move: "A short reset can help the body feel less exposed.",
      connect: "One safe person is enough for today.",
      reflect: "Write the truth without using the harsh story attached to it."
    };
  }

  if (issueId === "grief") {
    return {
      issueLabel: "grief",
      reset: "Let the body pause without demanding recovery — grief needs space, not speed.",
      focus: "Choose one very small task that belongs to today, not to the future.",
      move: "Gentle movement can help the body carry loss a little more softly.",
      connect: "One person who lets you grieve without fixing you is enough for today.",
      reflect: "Write what you miss and one small thing that still holds meaning."
    };
  }

  if (issueId === "trauma") {
    return {
      issueLabel: "trauma",
      reset: "Ground the body in this moment — slow breath, feel your feet, look at the room.",
      focus: "Keep the task very close to the present; do not plan too far ahead.",
      move: "Gentle movement reconnects the body to safety. Slow beats fast here.",
      connect: "A trusted person or a professional contact is the safest next human step.",
      reflect: "Write only what feels safe to name today — no pressure to go deeper."
    };
  }

  if (issueId === "addiction") {
    return {
      issueLabel: "addiction recovery",
      reset: "Interrupt the craving window with breath, water, and five minutes of delay.",
      focus: "Choose a task that fills the window where the urge usually wins.",
      move: "Physical movement is one of the strongest craving-interrupt tools available.",
      connect: "One honest check-in with a support contact or sponsor is the most powerful step.",
      reflect: "Write the trigger, the urge, and one thing you chose instead today."
    };
  }

  if (issueId === "health") {
    return {
      issueLabel: "health concern",
      reset: "Lower the anxiety around the symptom before it drives the next decision.",
      focus: "Pick one health action — appointment, note, or habit — that is small and real.",
      move: "Move within your current physical capacity, without pushing or avoiding.",
      connect: "A doctor, family member, or trusted person is the right next call.",
      reflect: "Write the symptom, the worry, and the one step that is actually in your control."
    };
  }

  if (issueId === "financial") {
    return {
      issueLabel: "financial stress",
      reset: "Lower the panic before you open another bill or calculation.",
      focus: "Pick one financial task — one entry, one call, one comparison — nothing more.",
      move: "A short walk can help break the loop of catastrophic financial thinking.",
      connect: "One trusted person or a financial counselor can help you see more clearly.",
      reflect: "Write the actual number you are working with and one concrete step."
    };
  }

  if (issueId === "relationship") {
    return {
      issueLabel: "relationship strain",
      reset: "Regulate before you reply — most relationship damage happens in a heightened state.",
      focus: "Pick one task that is entirely your own and does not need the other person.",
      move: "Movement helps create the distance you need before a difficult conversation.",
      connect: "A mediator, counselor, or trusted third person can help break the cycle.",
      reflect: "Write what you felt, what you needed, and what you can own from your side."
    };
  }

  if (issueId === "parenting") {
    return {
      issueLabel: "parenting challenge",
      reset: "You cannot pour from an empty space — rest is a parenting tool, not a failure.",
      focus: "Pick one small parenting task that you can close today without pressure.",
      move: "Move together with your child or alone — both restore a steadier parent.",
      connect: "Another parent, your partner, or a support network helps carry the weight.",
      reflect: "Write what your child needs today and what you need to give it sustainably."
    };
  }

  if (issueId === "academic") {
    return {
      issueLabel: "academic pressure",
      reset: "A short body reset between study blocks outperforms powering through.",
      focus: "Pick the one task that unblocks everything else — start there only.",
      move: "A 5-minute walk between sessions significantly improves retention and calm.",
      connect: "A classmate, mentor, or parent who understands the pressure helps.",
      reflect: "Write what you actually understood today, not just what you covered."
    };
  }

  if (issueId === "identity") {
    return {
      issueLabel: "identity exploration",
      reset: "Rest from performing or explaining yourself — just be in the quiet for a moment.",
      focus: "Pick one task that expresses who you genuinely are, not who you think you should be.",
      move: "Movement in a safe space can reconnect you with your body as your home.",
      connect: "One person who accepts you without conditions is more important than many.",
      reflect: "Write what feels true about who you are, separate from what others expect."
    };
  }

  return {
    issueLabel: "fear",
    reset: "Make the next step smaller than the fear expects.",
    focus: "Use a task that can finish before the fear gets louder.",
    move: "Move first, then decide from a steadier place.",
    connect: "Check in with someone safe before the fear grows.",
    reflect: "Write the fear and the next tiny fact-based step."
  };
}

function getPatternRoleFrame(identityId: IdentityId) {
  if (identityId === "student" || identityId === "child") {
    return {
      label: "Student",
      lens: "Protect study time, sleep, and one honest check-in.",
      next: "Keep the next test around class time, homework, and one trusted adult or mentor."
    };
  }

  if (identityId === "teacher") {
    return {
      label: "Teacher",
      lens: "Protect class transitions, planning time, and one quiet buffer.",
      next: "Keep the next test around lesson handoffs, marking, and one short reset between people."
    };
  }

  if (identityId === "doctor" || identityId === "nurse") {
    return {
      label: "Shift work",
      lens: "Protect handovers, hydration, and recovery after shift.",
      next: "Keep the next test around the shift pattern, handover quality, and one brief body reset."
    };
  }

  if (identityId === "officer" || identityId === "official") {
    return {
      label: "Duty",
      lens: "Protect debrief time, privacy, and calm judgment after duty.",
      next: "Keep the next test around duty blocks, handovers, and one short decompression break."
    };
  }

  if (
    identityId === "banker" ||
    identityId === "engineer" ||
    identityId === "lawyer" ||
    identityId === "professional" ||
    identityId === "entrepreneur"
  ) {
    return {
      label: "Work",
      lens: "Protect focus blocks, fewer tabs, and one clean decision lane.",
      next: "Keep the next test around one work block, one review step, and one short break."
    };
  }

  if (identityId === "parent" || identityId === "caregiver" || identityId === "homemaker") {
    return {
      label: "Care",
      lens: "Protect handoffs, short pauses, and one moment that belongs to you.",
      next: "Keep the next test around care tasks, a boundary, and one support request if needed."
    };
  }

  if (identityId === "retired") {
    return {
      label: "Retired",
      lens: "Protect routine, movement, and a slower pace that still has meaning.",
      next: "Keep the next test around one routine, one walk, and one connection that feels steady."
    };
  }

  return {
    label: "General",
    lens: "Protect one repeatable routine and one clear next step.",
    next: "Keep the next test around a small plan, one note, and one calmer return."
  };
}

function adaptPracticeChallenge(
  challenge: PlayChallenge,
  identityId: IdentityId,
  issueId: IssueId
): PlayChallenge {
  const role = getPracticeRoleFrame(identityId);
  const issue = getIssuePracticeTone(issueId);

  if (challenge.id === "reset") {
    return {
      ...challenge,
      subtitle: `${challenge.subtitle} · ${role.shortLabel}`,
      summary: `${challenge.summary} ${role.note}`,
      steps: [
        `Take 5 slow breaths with longer exhales before ${role.resetContext}.`,
        "Relax your shoulders, jaw, and hands.",
        "Drink water or stand up for a gentle body reset."
      ]
    };
  }

  if (challenge.id === "focus") {
    return {
      ...challenge,
      subtitle: `${challenge.subtitle} · ${role.shortLabel}`,
      summary: `${challenge.summary} ${role.note}`,
      steps: [
        `Choose one ${role.focusTask} that can finish in 5 minutes.`,
        `Remove one distraction that usually pulls you into ${issue.issueLabel}.`,
        "Finish the task and save the result."
      ]
    };
  }

  if (challenge.id === "move") {
    return {
      ...challenge,
      subtitle: `${challenge.subtitle} · ${role.shortLabel}`,
      summary: `${challenge.summary} ${role.note}`,
      steps: [
        `Walk, stretch, or step outside for 2 minutes after ${role.moveContext}.`,
        "Notice one sound, one sight, and one body feeling.",
        `Come back and rate your body on a calmer scale for ${issue.issueLabel}.`
      ]
    };
  }

  if (challenge.id === "connect") {
    return {
      ...challenge,
      subtitle: `${challenge.subtitle} · ${role.shortLabel}`,
      summary: `${challenge.summary} ${role.note}`,
      steps: [
        `Pick one trusted ${role.connectPerson}.`,
        `Send one simple message or check-in about ${issue.issueLabel}.`,
        "Confirm the next time you will connect."
      ]
    };
  }

  return {
    ...challenge,
    subtitle: `${challenge.subtitle} · ${role.shortLabel}`,
    summary: `${challenge.summary} ${role.note}`,
    steps: [
      `Write one sentence about what happened in ${role.reflectContext}.`,
      "Write one sentence about what you needed.",
      `Write one sentence about the next calm step for ${issue.issueLabel}.`
    ]
  };
}

