function nextAstroChatReply(question: string, ctx: {
  moonRashiId: number | null;
  moonRashiName: string;
  nakshatraLord: string | null;
  currentDasha: string | null;
  currentAntardasha: string | null;
  currentDashaYearsLeft: number | null;
  currentAntardashaYearsLeft: number | null;
  currentDashaStartedAtIso: string | null;
  currentDashaEndsAtIso: string | null;
  currentAntardashaStartedAtIso: string | null;
  currentAntardashaEndsAtIso: string | null;
  todayTithi: string;
  todayVara: string;
}): { category: AstroChatCategory; reply: string; remedy: string } {
  const cat = classifyAstroQuestion(question);
  const lines: string[] = [];

  if (ctx.moonRashiId === null) {
    lines.push(`Add your date of birth in Profile so I can read your Moon Rashi — the reply will be sharper.`);
    lines.push(`General direction for a ${cat} question: pause, name what you actually want, then take one small step that a wise friend would suggest.`);
    return {
      category: cat,
      reply: lines.join("\n\n"),
      remedy: `Light a diya at dusk. Chant Om Namah Shivaya 11 times. Add your birth details for a personalised remedy.`,
    };
  }

  const categoryActions: Record<AstroChatCategory, string> = {
    career: "Take one concrete move this week: apply, ask, or publish once. The phase rewards structure over waiting for perfect clarity.",
    relationship: "Speak directly but softly. Name the actual need, keep one boundary clean, and do not rely on hints.",
    health: "Simplify the routine. Sleep, water, meals, and one daily walk will stabilize the phase better than overthinking it.",
    money: "Track the next 30 days carefully, reduce leakage, and make one disciplined saving or repayment action.",
    family: "Keep the tone calm, repeat the important point once, and stop the loop of arguing the same thing in different words.",
    spiritual: "Use one steady practice every day. Repetition matters more than intensity in this phase.",
    timing: "Choose the smallest reversible step if the decision cannot wait; otherwise let the window mature a little longer.",
    identity: "Act like the person you are trying to become in one visible way today. Small consistency changes the pattern.",
    general: "Reduce confusion with one clear step and one clear boundary. The chart likes action that is simple and repeatable."
  };
  const currentDashaQuality = ctx.currentDasha ? summarizePlanetQuality(ctx.currentDasha) : "mixed influences";
  const currentAntardashaQuality = ctx.currentAntardasha ? summarizePlanetQuality(ctx.currentAntardasha) : "mixed influences";
  const dashaTiming = [
    ctx.currentAntardashaYearsLeft !== null ? `the current Antardasha has about ${formatPhaseSpan(ctx.currentAntardashaYearsLeft)} left` : null,
    ctx.currentDashaYearsLeft !== null ? `the broader Mahadasha has about ${formatPhaseSpan(ctx.currentDashaYearsLeft)} left` : null
  ].filter(Boolean).join(" and ");
  const phaseWindow = [
    ctx.currentDashaStartedAtIso && ctx.currentDashaEndsAtIso
      ? `Mahadasha started around ${formatApproxDate(ctx.currentDashaStartedAtIso)} and ends around ${formatApproxDate(ctx.currentDashaEndsAtIso)}`
      : null,
    ctx.currentAntardashaStartedAtIso && ctx.currentAntardashaEndsAtIso
      ? `Antardasha started around ${formatApproxDate(ctx.currentAntardashaStartedAtIso)} and ends around ${formatApproxDate(ctx.currentAntardashaEndsAtIso)}`
      : null,
  ].filter(Boolean).join(" • ");
  const domainOutlook = buildPhaseDomainOutlook(
    ctx.currentDasha && ctx.currentAntardasha
      ? { currentMahadasha: ctx.currentDasha, currentAntardasha: ctx.currentAntardasha }
      : null
  );

  // 1. Rashi lens
  lines.push(`What is happening for ${ctx.moonRashiName}: ${rashiCategoryLens(cat, ctx.moonRashiId)}`);

  // 2. Dasha lens
  if (ctx.currentDasha && ctx.currentAntardasha) {
    lines.push(
      `How it is happening: ${ctx.currentDasha} Mahadasha is the broad life lesson and ${ctx.currentAntardasha} Antardasha is the active sub-pattern. ${ctx.currentDasha} brings ${currentDashaQuality.toLowerCase()}, while ${ctx.currentAntardasha} adds ${currentAntardashaQuality.toLowerCase()}; that blend is what the chart is expressing right now.`
    );
  } else if (ctx.currentDasha) {
    lines.push(
      `How it is happening: you are in ${ctx.currentDasha} Mahadasha (${currentDashaQuality.toLowerCase()}). It is shaping the larger current and deciding which efforts can actually stick.`
    );
  }

  // 3. Timing lens
  if (dashaTiming.length > 0) {
    lines.push(`How long this phase lasts: ${dashaTiming}. These timings are approximate because they are derived from the birth date here; an exact birth time and location will sharpen the result.`);
  }
  if (phaseWindow.length > 0) {
    lines.push(`When it started and ends: ${phaseWindow}.`);
  }

  if (domainOutlook.length > 0) {
    lines.push(`Domain outlook from the same phase:`);
    domainOutlook.forEach((item) => {
      lines.push(`${item.domain}: ${item.verdict} — ${item.note}`);
    });
  }

  // 4. Practical action lens
  lines.push(`What to do now: ${categoryActions[cat]}.`);

  // 5. Today's Panchang lens
  lines.push(`Today’s Panchang: ${ctx.todayVara}, ${ctx.todayTithi}. If the decision can wait, use this window to observe once more before forcing the outcome.`);
  lines.push(`If you want, ask the same thing in a narrower way and I will go one layer deeper into the same phase.`);

  // 4. Remedy from the Rashi remedy pack
  const R = RASHI_REMEDIES[ctx.moonRashiId] ?? RASHI_REMEDIES[0];
  const lalKitabRemedies = buildLalKitabRemedies(ctx.currentDasha, ctx.currentAntardasha, cat);
  const remedy = [
    "Vedic remedy",
    `Mantra: ${R.mantra} — 108 times, morning after bath.`,
    `Gemstone: ${R.gem} (consult a Jyotishi before wearing).`,
    `Fast: ${R.fast} — sunrise to sunset, break with fruit.`,
    `Deity: offer flowers or a diya to ${R.deity}.`,
    `Food: ${R.food}.`,
    "",
    "Lal Kitab remedies",
    ...lalKitabRemedies,
  ].join("\n");

  return { category: cat, reply: lines.join("\n\n"), remedy };
}

type VedicEngineSource = "home" | "counseling" | "aihelp" | "manual";

interface VedicEngineIssueContext {
  issueText: string;
  issueLabel: string;
  issueId: IssueId;
  source: VedicEngineSource;
  receivedAtIso: string;
  autoAsk: boolean;
  autoAskedAtIso: string | null;
}

// High-precision Moon-chart astronomy helpers. These deliberately avoid any
// alternate natal prediction path: the solar longitude is used only for Panchang Tithi math.
const DEG_PER_NAKSHATRA = 360 / 27;
const DEG_PER_NAKSHATRA_PADA = DEG_PER_NAKSHATRA / 4;
const MS_PER_DAY = 86400000;
const VIMSHOTTARI_TOTAL_YEARS = 120;
const SIDEREAL_YEAR_MS = 365.256363004 * MS_PER_DAY;

type JanmaNakshatraInfo = {
  id: number;
  name: string;
  lord: string;
  pada: number;
  siderealMoonLongitude: number;
  degreesInNakshatra: number;
  fractionElapsed: number;
  balanceFraction: number;
  calculationPrecision: string;
};

function normalizeDegrees(value: number): number {
  return ((value % 360) + 360) % 360;
}

function degToRad(value: number): number {
  return (value * Math.PI) / 180;
}

function radToDeg(value: number): number {
  return (value * 180) / Math.PI;
}

// IST is assumed for all birth-time conversions since birth place is
// India-focused throughout this app (Panchang, Indian helplines, etc.).
// Without a stored timezone/coordinates this is the best available default —
// still far more accurate than ignoring birth time entirely (the prior bug).
const IST_OFFSET_MS = 5.5 * 60 * 60 * 1000;

// Combines birth date + birth time (local, assumed IST) into the correct UTC
// instant. Falls back to noon UTC only when no valid birth time is supplied,
// so users who haven't entered a birth time still get a (less precise) result
// instead of a crash. This is what actually fixes Rashi/Nakshatra/Dasha
// accuracy — previously birth time was collected from the user but never
// used in any Moon-longitude calculation, always defaulting to noon UTC
// regardless of the real birth time.
// Validates a calendar day against the actual days-in-month for the given
// year (accounting for leap years), instead of a blanket 1-31 range. Without
// this, JS's Date.UTC silently rolls invalid dates like Feb 30 or Apr 31 into
// the next month, shifting the Moon longitude / Nakshatra / Rashi / Dasha /
// Lagna calculations without any indication to the user that their entered
// birth date was reinterpreted.
function isValidCalendarDate(year: number, month: number, day: number): boolean {
  if (month < 1 || month > 12 || day < 1) return false;
  const isLeapYear = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, isLeapYear ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return day <= daysInMonth[month - 1];
}

function parseVedicBirthMoment(dob: string, birthTime?: string | null): Date | null {
  if (!dob || dob.length < 10) return null;
  const dateMatch = /^(\d{4})-(\d{2})-(\d{2})/.exec(dob.trim());
  if (!dateMatch) return null;
  const year = Number(dateMatch[1]);
  const month = Number(dateMatch[2]);
  const day = Number(dateMatch[3]);
  if (!year || !isValidCalendarDate(year, month, day)) return null;

  const timeMatch = birthTime && /^\d{2}:\d{2}$/.test(birthTime) ? birthTime : null;
  if (!timeMatch) {
    const parsed = new Date(Date.UTC(year, month - 1, day, 12, 0, 0));
    return isNaN(parsed.getTime()) ? null : parsed;
  }
  const hour = Number(timeMatch.slice(0, 2));
  const minute = Number(timeMatch.slice(3, 5));
  if (isNaN(hour) || isNaN(minute) || hour > 23 || minute > 59) {
    const parsed = new Date(Date.UTC(year, month - 1, day, 12, 0, 0));
    return isNaN(parsed.getTime()) ? null : parsed;
  }
  // Construct the local (IST) clock time as if it were UTC, then subtract the
  // IST offset to get the true UTC instant.
  const localAsUtc = Date.UTC(year, month - 1, day, hour, minute, 0);
  const trueUtc = new Date(localAsUtc - IST_OFFSET_MS);
  return isNaN(trueUtc.getTime()) ? null : trueUtc;
}

function parseVedicDateAtNoonUtc(value: string): Date | null {
  if (!value || value.length < 10) return null;
  const match = /^(\d{4})-(\d{2})-(\d{2})/.exec(value.trim());
  if (match) {
    const year = Number(match[1]);
    const month = Number(match[2]);
    const day = Number(match[3]);
    if (!year || !isValidCalendarDate(year, month, day)) return null;
    const parsed = new Date(Date.UTC(year, month - 1, day, 12, 0, 0));
    return isNaN(parsed.getTime()) ? null : parsed;
  }
  const parsed = new Date(value);
  return isNaN(parsed.getTime()) ? null : parsed;
}

function julianDay(date: Date): number {
  return date.getTime() / MS_PER_DAY + 2440587.5;
}

function lahiriAyanamsaDegrees(jd: number): number {
  // Lahiri/Chitrapaksha approximation. Reference around J2000 is ~23.85675°.
  // Precession drift is ~50.29 arcseconds/year. This keeps nakshatra/rashi
  // boundaries stable enough for app-level birth-date calculations without a
  // heavy native ephemeris dependency.
  const tropicalYear = 365.242189;
  const yearsFromJ2000 = (jd - 2451545.0) / tropicalYear;
  return 23.85675 + yearsFromJ2000 * (50.290966 / 3600);
}

function getApproxTropicalMoonLongitude(date: Date): number {
  // ELP2000-82B lunar theory via astronomy-engine — the established model
  // used by professional ephemeris software, accurate to arc-seconds. This
  // replaces the previous hand-rolled ~15-term truncated series (error up to
  // ~1 degree) with the full established theory.
  return normalizeDegrees(Astronomy.EclipticGeoMoon(date).lon);
}

function getApproxTropicalSunLongitude(date: Date): number {
  // VSOP87 solar theory via astronomy-engine (apparent geocentric true
  // ecliptic longitude of date, including aberration and nutation) — the
  // same established model used by professional ephemeris software.
  return normalizeDegrees(Astronomy.SunPosition(date).elon);
}

// True obliquity of the ecliptic at a given moment, from astronomy-engine's
// nutation/precession model. Needed for the real Ascendant formula.
function getTrueObliquityDegrees(date: Date): number {
  return Astronomy.e_tilt(Astronomy.MakeTime(date)).tobl;
}

// Greenwich Apparent Sidereal Time, in degrees [0, 360). Needed (together with
// observer longitude) to get Local Sidereal Time for the Ascendant formula.
function getGreenwichSiderealTimeDegrees(date: Date): number {
  return normalizeDegrees(Astronomy.SiderealTime(date) * 15);
}

// Geocodes a free-text birth place into {lat, lon} using OpenStreetMap
// Nominatim — a free, established, no-API-key-required geocoding service.
// Only the place text is sent, never the person's name or birth date/time.
// Used solely to compute the real Ascendant (Lagna); every other Vedic
// calculation (Rashi, Nakshatra, Dasha) already works from date+time alone
// and does not depend on this.
async function geocodeBirthPlace(place: string): Promise<{ lat: number; lon: number } | null> {
  const trimmed = place.trim();
  if (trimmed.length < 3) return null;
  try {
    const url = `https://nominatim.openstreetmap.org/search?format=json&limit=1&q=${encodeURIComponent(trimmed)}`;
    const response = await fetch(url, {
      headers: {
        // Nominatim's usage policy requires an identifying User-Agent.
        "User-Agent": "AethonBeacon/1.0 (birth-place geocoding for Vedic Ascendant calculation)",
        Accept: "application/json",
      },
    });
    if (!response.ok) return null;
    const results = await response.json();
    if (!Array.isArray(results) || results.length === 0) return null;
    const lat = parseFloat(results[0].lat);
    const lon = parseFloat(results[0].lon);
    if (isNaN(lat) || isNaN(lon)) return null;
    return { lat, lon };
  } catch {
    return null;
  }
}

// Real Ascendant (Lagna) via Local Sidereal Time + true obliquity + latitude —
// the standard spherical-astronomy formula (Meeus, "Astronomical Algorithms",
// and universally used in professional astrology software). Falls back to
// null when lat/lon aren't available yet (caller should use the Sun-anchored
// approximation instead).
//
// NOTE: the (y, x) signs below are intentionally the mirror of the naive
// textbook write-up of this formula. The un-mirrored version computes the
// DESCENDANT (180 deg opposite the true rising sign), not the Ascendant --
// confirmed by cross-checking against the Midheaven (a valid Ascendant sits
// ~90 deg from the MC; the un-mirrored formula was landing ~268 deg from
// it) and against a real reference chart (10 Aug 1977, 10:45 IST, Jammu:
// true Lagna is Kanya/Virgo, sidereal ~175 deg; the un-mirrored formula
// produced Meena/Pisces, sidereal ~355 deg -- exactly 180 deg off).
function getPreciseAscendantSiderealDegrees(date: Date, latDeg: number, lonDeg: number): number {
  const gastDeg = getGreenwichSiderealTimeDegrees(date);
  const lstDeg = normalizeDegrees(gastDeg + lonDeg); // east longitude positive
  const eps = getTrueObliquityDegrees(date);

  const theta = degToRad(lstDeg);
  const phi = degToRad(latDeg);
  const epsRad = degToRad(eps);

  const y = Math.cos(theta);
  const x = -(Math.sin(epsRad) * Math.tan(phi) + Math.cos(epsRad) * Math.sin(theta));
  const ascTropical = normalizeDegrees(radToDeg(Math.atan2(y, x)));

  const ayanamsa = lahiriAyanamsaDegrees(julianDay(date));
  return normalizeDegrees(ascTropical - ayanamsa);
}

function getSiderealMoonLongitude(date: Date): number {
  return normalizeDegrees(getApproxTropicalMoonLongitude(date) - lahiriAyanamsaDegrees(julianDay(date)));
}

function buildNakshatraFromMoonLongitude(siderealMoonLongitude: number, usedExactBirthTime: boolean = false): JanmaNakshatraInfo {
  const longitude = normalizeDegrees(siderealMoonLongitude);
  const id = Math.min(26, Math.floor(longitude / DEG_PER_NAKSHATRA));
  const degreesInNakshatra = longitude - id * DEG_PER_NAKSHATRA;
  const pada = Math.min(4, Math.floor(degreesInNakshatra / DEG_PER_NAKSHATRA_PADA) + 1);
  const fractionElapsed = Math.max(0, Math.min(1, degreesInNakshatra / DEG_PER_NAKSHATRA));
  return {
    id,
    name: NAKSHATRAS[id],
    lord: NAKSHATRA_LORDS[id],
    pada,
    siderealMoonLongitude: longitude,
    degreesInNakshatra,
    fractionElapsed,
    balanceFraction: 1 - fractionElapsed,
    calculationPrecision: usedExactBirthTime
      ? "sidereal Moon longitude at exact birth time (IST assumed), Lahiri ayanamsa approximation"
      : "sidereal Moon longitude at noon UTC fallback (no birth time entered), Lahiri ayanamsa approximation",
  };
}

// Janma Nakshatra from sidereal Moon longitude at the actual birth moment.
// Passing birthTime matters: the Moon moves ~0.55°/hour, so using noon UTC
// regardless of real birth time (the old behaviour) could shift the result
// by several degrees — enough to flip nakshatra/pada near a boundary and
// throw off every downstream Dasha calculation.
function getJanmaNakshatra(dob: string, birthTime?: string | null): JanmaNakshatraInfo | null {
  const d = parseVedicBirthMoment(dob, birthTime);
  if (!d) return null;
  const usedExactBirthTime = !!(birthTime && /^\d{2}:\d{2}$/.test(birthTime));
  return buildNakshatraFromMoonLongitude(getSiderealMoonLongitude(d), usedExactBirthTime);
}

