function getMoonChartPlanetCategoryScore(planet: string | null | undefined, category: MoonChart48Category): number {
  if (!planet) return 0;
  return PLANET_MOON_CHART_STRENGTH[planet]?.[category] ?? 0;
}

function getMoonChartHouseScore(category: MoonChart48Category, house: number): number {
  const specific = HOUSE_MOON_CHART_STRENGTH[category]?.[house];
  if (typeof specific === "number") return specific;
  if (house === 1 || house === 5 || house === 9) return 4;
  if (house === 4 || house === 7 || house === 10) return 3;
  if (house === 3 || house === 6 || house === 11) return 2;
  if (house === 8 || house === 12) return -4;
  return 0;
}

function describeMoonChartScore(score: number, category: MoonChart48Category): string {
  const categoryFocus: Record<MoonChart48Category, string> = {
    self: "identity and confidence",
    mind: "mental and emotional steadiness",
    body: "body rhythm and routine",
    relationship: "bonding, trust, and communication",
    work: "duty, visibility, and execution",
    money: "resources, saving, and obligations",
    family: "home, speech, and nurturance",
    spiritual: "faith, release, and dharma",
    risk: "caution, hidden pressure, and restraint",
    growth: "learning, courage, and future direction",
  };
  if (score >= 82) return `${categoryFocus[category]} are strongly supported`;
  if (score >= 68) return `${categoryFocus[category]} are workable with steady choices`;
  if (score >= 50) return `${categoryFocus[category]} need balance and timing`;
  return `${categoryFocus[category]} need extra caution and grounding`;
}

function buildMoonChart48DimensionEngine(input: {
  rashiId: number;
  janmaNakshatra: ReturnType<typeof getJanmaNakshatra>;
  dashaState: VimshottariDashaState | null;
  tithi: ReturnType<typeof getTodayTithi>;
  vara: typeof VARA_INFO[0];
  // Optional: real Ascendant sign (0-11, sidereal), from getLagnaFromBirthDetails.
  // The Moon chart (Chandra Kundali) stays the primary anchor -- Vedic daily
  // prediction has traditionally leaned on the Moon chart -- but the Lagna
  // now adds a secondary confirming/tempering layer, since the Ascendant is
  // classically the chart of the physical self/body/personality specifically.
  lagnaId?: number | null;
}): MoonChart48Reading[] {
  const rashi = VEDIC_RASHIS[input.rashiId] ?? VEDIC_RASHIS[0];
  const lagnaRashi = typeof input.lagnaId === "number" ? VEDIC_RASHIS[input.lagnaId] ?? null : null;
  const lagnaLord = lagnaRashi ? lagnaRashi.lord.split(" ")[0] : null;
  const nakshatra = input.janmaNakshatra;
  const nakshatraId = nakshatra?.id ?? 0;
  const nakshatraLord = nakshatra?.lord ?? "Chandra";
  const pada = nakshatra?.pada ?? 1;
  const degreesInNakshatra = nakshatra?.degreesInNakshatra ?? 0;
  const lunarFinePulse = ((degreesInNakshatra / DEG_PER_NAKSHATRA) - 0.5) * 10;
  const tithiNumber = input.tithi?.number ?? 1;
  const tithiBalance = tithiNumber === 11 ? 5 : tithiNumber === 4 || tithiNumber === 8 || tithiNumber === 14 ? -4 : tithiNumber <= 5 ? 2 : 0;
  const varaPlanet = input.vara?.planet?.split(" ")[0] ?? "Chandra";
  const maha = input.dashaState?.currentMahadasha ?? nakshatraLord;
  const antar = input.dashaState?.currentAntardasha ?? nakshatraLord;

  return MOON_CHART_48_BLUEPRINTS.map((dimension, index) => {
    const houseScore = getMoonChartHouseScore(dimension.category, dimension.house);
    const mahaScore = getMoonChartPlanetCategoryScore(maha, dimension.category);
    const antarScore = getMoonChartPlanetCategoryScore(antar, dimension.category);
    const nakshatraScore = getMoonChartPlanetCategoryScore(nakshatraLord, dimension.category);
    const varaScore = getMoonChartPlanetCategoryScore(varaPlanet, dimension.category) * 0.25;
    const padaStability = pada === 2 || pada === 3 ? 2 : 0;
    const moonSignElementBias =
      rashi.element.includes("Jal") && (dimension.category === "mind" || dimension.category === "family" || dimension.category === "spiritual") ? 3 :
      rashi.element.includes("Agni") && (dimension.category === "self" || dimension.category === "work" || dimension.category === "growth") ? 3 :
      rashi.element.includes("Prithvi") && (dimension.category === "body" || dimension.category === "money" || dimension.category === "family") ? 3 :
      rashi.element.includes("Vayu") && (dimension.category === "relationship" || dimension.category === "growth" || dimension.category === "work") ? 3 : 0;

    // Lagna (Ascendant) overlay -- secondary to the Moon chart. Lagna lord's
    // classical significations plus the Ascendant sign's element, with extra
    // weight on "self"/"body" since Lagna specifically governs physical
    // self, vitality, and personality in Vedic astrology.
    const lagnaLordScore = lagnaLord ? getMoonChartPlanetCategoryScore(lagnaLord, dimension.category) : 0;
    const lagnaElementBias = lagnaRashi
      ? (lagnaRashi.element.includes("Jal") && (dimension.category === "mind" || dimension.category === "family" || dimension.category === "spiritual") ? 2.5 :
         lagnaRashi.element.includes("Agni") && (dimension.category === "self" || dimension.category === "work" || dimension.category === "growth") ? 2.5 :
         lagnaRashi.element.includes("Prithvi") && (dimension.category === "body" || dimension.category === "money" || dimension.category === "family") ? 2.5 :
         lagnaRashi.element.includes("Vayu") && (dimension.category === "relationship" || dimension.category === "growth" || dimension.category === "work") ? 2.5 : 0)
      : 0;
    const lagnaSelfBodyEmphasis = lagnaRashi && (dimension.category === "self" || dimension.category === "body") ? 3 : 0;

    const raw = 60
      + houseScore * 1.55
      + mahaScore * 0.85
      + antarScore * 0.65
      + nakshatraScore * 0.4
      + varaScore
      + moonSignElementBias
      + tithiBalance
      + lunarFinePulse * 0.35
      + lagnaLordScore * 0.5
      + lagnaElementBias
      + lagnaSelfBodyEmphasis
      + ((nakshatraId + index) % 3 - 1) * dimension.weight;

    const score = clampMoonScore(raw);
    const verdict = moonChartVerdict(score);
    const focus = describeMoonChartScore(score, dimension.category);
    const dashaText = input.dashaState ? `${maha} Mahadasha / ${antar} Antardasha` : `${nakshatraLord} Nakshatra-lord phase`;
    const remedyPack = moonChartCategoryRemedyPack(dimension.category, rashi.name);
    const scoreReason = buildMoonChartScoreReason({
      houseScore,
      mahaScore,
      antarScore,
      nakshatraScore,
      varaScore,
      tithiBalance,
      moonSignElementBias,
      lunarFinePulse: lunarFinePulse * 0.35,
      house: dimension.house,
      category: dimension.category,
      maha,
      antar,
      nakshatraLord,
      varaPlanet,
      lagnaRashiName: lagnaRashi?.name ?? null,
      lagnaLord,
      lagnaLordScore: lagnaLordScore * 0.5,
      lagnaElementBias: lagnaElementBias + lagnaSelfBodyEmphasis,
    });
    const interpretation = `In plain language, ${dimension.label.toLowerCase()} belongs to ${moonChartCategoryMeaning(dimension.category)}. ${moonChartVerdictTone(verdict)}`;

    return {
      ...dimension,
      score,
      verdict,
      prediction: `From Moon Rashi ${rashi.name}${nakshatra ? `, ${nakshatra.name} Nakshatra pada ${pada}` : ""}${lagnaRashi ? `, with Lagna ${lagnaRashi.name}` : ""}, ${dimension.label.toLowerCase()} shows ${focus} today. The reading is calculated through Moon-house ${dimension.house}, ${dashaText}, ${input.tithi.name} ${input.tithi.paksha}, and ${input.vara.en}${lagnaRashi ? `, tempered by the Ascendant in ${lagnaRashi.name}` : ""}.`,
      interpretation,
      scoreReason,
      remedy: moonChartCategoryRemedy(dimension.category, rashi.name),
      remedyTitle: remedyPack.title,
      remedySteps: remedyPack.steps,
      calculationBasis: `Moon-chart basis (primary): sidereal Moon ${nakshatra?.siderealMoonLongitude.toFixed(2) ?? "n/a"}°; Janma Rashi ${rashi.name}; Nakshatra ${nakshatra?.name ?? "approximated"}; pada ${pada}; house ${dimension.house} from Moon; dasha ${maha}/${antar}; tithi ${input.tithi.number}.${lagnaRashi ? ` Ascendant overlay (secondary): Lagna ${lagnaRashi.name}, lord ${lagnaLord}.` : ""}`,
      visualAngle: (index % 12) * 30,
      visualDepth: Math.max(0.12, Math.min(1, score / 100)),
    };
  });
}

function summarizeMoonChart48(readings: MoonChart48Reading[]): { top: MoonChart48Reading[]; careful: MoonChart48Reading[]; average: number } {
  const sorted = [...readings].sort((a, b) => b.score - a.score);
  const careful = [...readings].sort((a, b) => a.score - b.score).slice(0, 4);
  const average = readings.length ? Math.round(readings.reduce((sum, item) => sum + item.score, 0) / readings.length) : 0;
  return { top: sorted.slice(0, 6), careful, average };
}

// ── Error Boundary ─────────────────────────────────────────────────────────
class AppErrorBoundary extends React.Component<
  { children: React.ReactNode },
  { hasError: boolean; errorMessage: string }
> {
  constructor(props: { children: React.ReactNode }) {
    super(props);
    this.state = { hasError: false, errorMessage: "" };
  }
  static getDerivedStateFromError(error: Error) {
    return { hasError: true, errorMessage: error?.message ?? "Unknown error" };
  }
  componentDidCatch(error: Error, info: React.ErrorInfo) {
    console.error("[AethonBeacon] Render error:", error, info);
  }
  render() {
    if (this.state.hasError) {
      return (
        <View style={{ flex: 1, backgroundColor: "#050D10", alignItems: "center", justifyContent: "center", padding: 32 }}>
          <Text style={{ fontSize: 40, marginBottom: 16 }}>⚠️</Text>
          <Text style={{ color: "#63DED0", fontSize: 18, fontWeight: "700", marginBottom: 8, textAlign: "center" }}>
            Something went wrong
          </Text>
          <Text style={{ color: "#94A3B8", fontSize: 14, textAlign: "center", marginBottom: 24, lineHeight: 20 }}>
            Aethon Beacon hit an unexpected error. Your data is safe — restart the app to continue.
          </Text>
          <Text style={{ color: "#475569", fontSize: 11, textAlign: "center", fontFamily: "monospace" }}>
            {this.state.errorMessage}
          </Text>
        </View>
      );
    }
    return this.props.children;
  }
}

// ── Per-tab error boundary — isolates crashes to a single tab ─────────────
class TabErrorBoundary extends React.Component<
  { children: React.ReactNode; tabName: string },
  { hasError: boolean }
> {
  constructor(props: { children: React.ReactNode; tabName: string }) {
    super(props);
    this.state = { hasError: false };
  }
  static getDerivedStateFromError() {
    return { hasError: true };
  }
  componentDidCatch(error: Error, info: React.ErrorInfo) {
    console.error(`[AethonBeacon] Tab "${this.props.tabName}" crashed:`, error, info);
  }
  render() {
    if (this.state.hasError) {
      return (
        <View style={{ flex: 1, alignItems: "center", justifyContent: "center", padding: 32, backgroundColor: "#050D10" }}>
          <Text style={{ fontSize: 32, marginBottom: 12 }}>⚠️</Text>
          <Text style={{ color: "#63DED0", fontSize: 16, fontWeight: "700", marginBottom: 8, textAlign: "center" }}>
            This section had an issue
          </Text>
          <Text style={{ color: "#94A3B8", fontSize: 13, textAlign: "center", lineHeight: 20 }}>
            Your data is safe. Switch to another tab and come back to refresh this section.
          </Text>
          <Pressable
            onPress={() => this.setState({ hasError: false })}
            style={{ marginTop: 20, backgroundColor: "#0F3D5E", borderRadius: 10, paddingHorizontal: 20, paddingVertical: 10 }}
            accessibilityRole="button"
          >
            <Text style={{ color: "#63DED0", fontSize: 13, fontWeight: "700" }}>Try again</Text>
          </Pressable>
        </View>
      );
    }
    return this.props.children;
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// EXIT REPORT ENGINE
// ─────────────────────────────────────────────────────────────────────────────

type SessionEvent = {
  type: "tab_visit" | "issue_detected" | "guidance_viewed" | "checkin" | "counseling_turn" | "journal_written" | "horoscope_viewed" | "birth_chart_viewed" | "meditation" | "community";
  label: string;
  detail?: string;
  ts: number;
};

type DailyVisitReport = {
  userName: string;
  sessionDurationMins: number;
  tabsVisited: string[];
  issuesDetected: string[];
  guidanceTopics: string[];
  checkInsLogged: number;
  counselingTurns: number;
  journalWritten: boolean;
  moodScore: number | null;
  moodLabel: string | null;
  strengths: string[];
  focusAreas: string[];
  tomorrowRecommendations: string[];
  overallSummary: string;
  generatedAt: string;
};

const EXIT_REPORT_ISSUE_LABELS: Record<string, string> = {
  general: "General wellbeing",
  anger: "Anger & frustration",
  anxiety: "Anxiety & worry",
  fear: "Fear & phobias",
  overconfidence: "Overconfidence",
  stigma: "Social stigma",
  burnout: "Burnout & exhaustion",
  loneliness: "Loneliness & isolation",
  grief: "Grief & loss",
  identity: "Identity & self-worth",
  health: "Health concerns",
  financial: "Financial stress",
  relationship: "Relationship issues",
  parenting: "Parenting challenges",
  trauma: "Trauma & PTSD",
  academic: "Academic pressure",
  addiction: "Addiction & habits",
};

function generateDailyVisitReport(
  userName: string,
  sessionStartTs: number,
  events: SessionEvent[],
  issueGuideId: string,
  entries: { score: number; toneLabel: string }[],
): DailyVisitReport {
  const now = Date.now();
  const durationMins = Math.max(1, Math.round((now - sessionStartTs) / 60000));

  // Deduplicate tab visits
  const tabsVisited = [...new Set(
    events.filter(e => e.type === "tab_visit").map(e => e.label)
  )];

  // Issues detected this session
  const issueEvents = events.filter(e => e.type === "issue_detected");
  const issuesDetected = [...new Set(
    issueEvents.map(e => EXIT_REPORT_ISSUE_LABELS[e.label] ?? e.label)
  )];
  if (issuesDetected.length === 0 && issueGuideId !== "general") {
    issuesDetected.push(EXIT_REPORT_ISSUE_LABELS[issueGuideId] ?? issueGuideId);
  }

  // Guidance topics
  const guidanceTopics = [...new Set(
    events.filter(e => e.type === "guidance_viewed").map(e => e.label)
  )];

  // Check-ins
  const checkInsLogged = events.filter(e => e.type === "checkin").length;

  // Counseling
  const counselingTurns = events.filter(e => e.type === "counseling_turn").length;

  // Journal
  const journalWritten = events.some(e => e.type === "journal_written");

  // Mood from today's entries. Callers are expected to pre-filter `entries`
  // down to today's check-ins before calling this function (both call sites
  // do this via createdAt); this function trusts that contract rather than
  // re-filtering, since its parameter type doesn't carry a date field.
  const todayEntries = entries;
  const avgScore = todayEntries.length > 0
    ? Math.round(todayEntries.reduce((s, e) => s + e.score, 0) / todayEntries.length)
    : null;
  const latestToneLabel = todayEntries[0]?.toneLabel ?? null;

  // Strengths from activities
  const strengths: string[] = [];
  if (checkInsLogged > 0) strengths.push("Self-awareness check-in completed");
  if (journalWritten) strengths.push("Reflective journaling practiced");
  if (counselingTurns > 0) strengths.push("Engaged in guided counseling");
  if (tabsVisited.includes("Meditation")) strengths.push("Meditation session started");
  if (tabsVisited.includes("Community")) strengths.push("Community connection explored");
  if (tabsVisited.includes("Guidance")) strengths.push("Guidance path explored");
  if (tabsVisited.includes("Tones")) strengths.push("Sound healing tones practiced");
  if (tabsVisited.includes("Vedic / Horoscope")) strengths.push("Vedic insight checked");
  if (strengths.length === 0) strengths.push("Showed up for your mental health today");

  // Focus areas
  const focusAreas: string[] = [];
  if (issuesDetected.length > 0) focusAreas.push(...issuesDetected.slice(0, 3));
  if (focusAreas.length === 0) focusAreas.push("General wellbeing maintenance");

  // Tomorrow's recommendations
  const recs: string[] = [];
  if (checkInsLogged === 0) recs.push("Log a mood check-in tomorrow to track your emotional baseline");
  if (!journalWritten) recs.push("Try a 5-minute journal entry — even 3 sentences helps");
  if (counselingTurns === 0) recs.push("Explore the guided counseling session for deeper insight");
  if (avgScore !== null && avgScore < 4) recs.push("Practice the breathing or calm-tone exercises to ease tension");
  if (tabsVisited.length < 3) recs.push("Explore the Wisdom or Community tabs for fresh perspective");
  recs.push("Keep your streak alive — consistency is where transformation happens");

  // Summary
  const activityCount = tabsVisited.length + (checkInsLogged > 0 ? 1 : 0) + (journalWritten ? 1 : 0) + (counselingTurns > 0 ? 1 : 0);
  const moodPhrase = avgScore !== null
    ? `Your mood registered at ${avgScore}/7 (${latestToneLabel ?? "balanced"})`
    : "No mood score logged";
  const issuePhrase = issuesDetected.length > 0
    ? `Key focus: ${issuesDetected.slice(0, 2).join(" & ")}`
    : "General wellbeing maintained";

  const overallSummary =
    `You spent ${durationMins} minute${durationMins !== 1 ? "s" : ""} with Aethon Beacon today. ` +
    `${moodPhrase}. ${issuePhrase}. ` +
    `${activityCount} activit${activityCount !== 1 ? "ies" : "y"} completed across ${tabsVisited.length || 1} section${tabsVisited.length !== 1 ? "s" : ""}. ` +
    `${strengths[0] ?? "Well done for showing up"}.`;

  return {
    userName,
    sessionDurationMins: durationMins,
    tabsVisited,
    issuesDetected,
    guidanceTopics,
    checkInsLogged,
    counselingTurns,
    journalWritten,
    moodScore: avgScore,
    moodLabel: latestToneLabel,
    strengths,
    focusAreas,
    tomorrowRecommendations: recs.slice(0, 4),
    overallSummary,
    generatedAt: new Date().toLocaleString("en-IN", { dateStyle: "full", timeStyle: "short" }),
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// EXIT REPORT MODAL
// ─────────────────────────────────────────────────────────────────────────────

function ExitReportModal({
  visible,
  report,
  onClose,
  onShare,
}: {
  visible: boolean;
  report: DailyVisitReport | null;
  onClose: () => void;
  onShare: (report: DailyVisitReport) => void;
}) {
  if (!report) return null;

  const scoreColor = report.moodScore !== null
    ? (report.moodScore >= 5 ? "#22D3EE" : report.moodScore >= 3 ? "#FBBF24" : "#F87171")
    : "#94A3B8";

  return (
    <Modal
      visible={visible}
      animationType="slide"
      transparent={false}
      onRequestClose={onClose}
    >
      <View style={{ flex: 1, backgroundColor: "#050D14" }}>
        {/* Header */}
        <View style={{
          paddingTop: Platform.OS === "ios" ? 54 : 40,
          paddingHorizontal: 20,
          paddingBottom: 16,
          borderBottomWidth: 1,
          borderBottomColor: "rgba(34,211,238,0.15)",
          flexDirection: "row",
          alignItems: "center",
          justifyContent: "space-between",
        }}>
          <View>
            <Text style={{ color: "#22D3EE", fontSize: 12, fontWeight: "700", letterSpacing: 2, textTransform: "uppercase" }}>
              Today's Visit Report
            </Text>
            <Text style={{ color: "#E8F4F0", fontSize: 18, fontWeight: "900", marginTop: 2 }}>
              {report.userName || "Your Day with Aethon"}
            </Text>
            <Text style={{ color: "#64748B", fontSize: 11, marginTop: 2 }}>{report.generatedAt}</Text>
          </View>
          <Pressable
            onPress={onClose}
            style={({ pressed }) => ({
              width: 36, height: 36, borderRadius: 18,
              backgroundColor: pressed ? "#1E3A4A" : "#0C1A2E",
              alignItems: "center", justifyContent: "center",
              borderWidth: 1, borderColor: "rgba(34,211,238,0.2)",
            })}
          >
            <Text style={{ color: "#94A3B8", fontSize: 18, lineHeight: 20 }}>✕</Text>
          </Pressable>
        </View>

        <ScrollView
          contentContainerStyle={{ padding: 20, paddingBottom: 50 }}
          showsVerticalScrollIndicator={false}
        >
          {/* Summary Card */}
          <View style={{
            backgroundColor: "#0C1A2E",
            borderRadius: 14,
            padding: 16,
            borderWidth: 1,
            borderColor: "rgba(34,211,238,0.25)",
            marginBottom: 16,
          }}>
            <Text style={{ color: "#22D3EE", fontSize: 11, fontWeight: "700", letterSpacing: 1.5, marginBottom: 8, textTransform: "uppercase" }}>
              📋 Session Summary
            </Text>
            <Text style={{ color: "#CBD5E1", fontSize: 14, lineHeight: 22 }}>{report.overallSummary}</Text>
          </View>

          {/* Stats Row */}
          <View style={{ flexDirection: "row", gap: 10, marginBottom: 16 }}>
            {[
              { label: "Duration", value: `${report.sessionDurationMins}m`, icon: "⏱" },
              { label: "Mood", value: report.moodScore !== null ? `${report.moodScore}/7` : "—", icon: "🎯", color: scoreColor },
              { label: "Activities", value: String((report.checkInsLogged > 0 ? 1 : 0) + (report.journalWritten ? 1 : 0) + (report.counselingTurns > 0 ? 1 : 0) + report.tabsVisited.length), icon: "✅" },
            ].map((stat) => (
              <View key={stat.label} style={{
                flex: 1, backgroundColor: "#0C1A2E", borderRadius: 12, padding: 12,
                alignItems: "center", borderWidth: 1, borderColor: "rgba(34,211,238,0.15)",
              }}>
                <Text style={{ fontSize: 20, marginBottom: 4 }}>{stat.icon}</Text>
                <Text style={{ color: stat.color ?? "#E8F4F0", fontSize: 16, fontWeight: "900" }}>{stat.value}</Text>
                <Text style={{ color: "#64748B", fontSize: 10, marginTop: 2 }}>{stat.label}</Text>
              </View>
            ))}
          </View>

          {/* Issues Detected */}
          {report.issuesDetected.length > 0 && (
            <View style={{ backgroundColor: "#0C1A2E", borderRadius: 14, padding: 16, borderWidth: 1, borderColor: "rgba(251,191,36,0.2)", marginBottom: 14 }}>
              <Text style={{ color: "#FBBF24", fontSize: 11, fontWeight: "700", letterSpacing: 1.5, marginBottom: 10, textTransform: "uppercase" }}>
                🔍 Issues Identified
              </Text>
              {report.issuesDetected.map((issue, i) => (
                <View key={i} style={{ flexDirection: "row", alignItems: "flex-start", marginBottom: 6 }}>
                  <Text style={{ color: "#FBBF24", fontSize: 12, marginRight: 8, marginTop: 2 }}>▸</Text>
                  <Text style={{ color: "#CBD5E1", fontSize: 14, flex: 1, lineHeight: 20 }}>{issue}</Text>
                </View>
              ))}
            </View>
          )}

          {/* Guidance Received */}
          {report.guidanceTopics.length > 0 && (
            <View style={{ backgroundColor: "#0C1A2E", borderRadius: 14, padding: 16, borderWidth: 1, borderColor: "rgba(34,211,238,0.2)", marginBottom: 14 }}>
              <Text style={{ color: "#22D3EE", fontSize: 11, fontWeight: "700", letterSpacing: 1.5, marginBottom: 10, textTransform: "uppercase" }}>
                🧭 Guidance Provided
              </Text>
              {report.guidanceTopics.map((topic, i) => (
                <View key={i} style={{ flexDirection: "row", alignItems: "flex-start", marginBottom: 6 }}>
                  <Text style={{ color: "#22D3EE", fontSize: 12, marginRight: 8, marginTop: 2 }}>▸</Text>
                  <Text style={{ color: "#CBD5E1", fontSize: 14, flex: 1, lineHeight: 20 }}>{topic}</Text>
                </View>
              ))}
            </View>
          )}

          {/* Strengths */}
          <View style={{ backgroundColor: "#0A1C0F", borderRadius: 14, padding: 16, borderWidth: 1, borderColor: "rgba(34,197,94,0.2)", marginBottom: 14 }}>
            <Text style={{ color: "#4ADE80", fontSize: 11, fontWeight: "700", letterSpacing: 1.5, marginBottom: 10, textTransform: "uppercase" }}>
              💪 Today's Strengths
            </Text>
            {report.strengths.map((s, i) => (
              <View key={i} style={{ flexDirection: "row", alignItems: "flex-start", marginBottom: 6 }}>
                <Text style={{ color: "#4ADE80", fontSize: 12, marginRight: 8, marginTop: 2 }}>✓</Text>
                <Text style={{ color: "#CBD5E1", fontSize: 14, flex: 1, lineHeight: 20 }}>{s}</Text>
              </View>
            ))}
          </View>

          {/* Tomorrow's Focus */}
          <View style={{ backgroundColor: "#1A0C2E", borderRadius: 14, padding: 16, borderWidth: 1, borderColor: "rgba(167,139,250,0.25)", marginBottom: 14 }}>
            <Text style={{ color: "#A78BFA", fontSize: 11, fontWeight: "700", letterSpacing: 1.5, marginBottom: 10, textTransform: "uppercase" }}>
              🌅 Tomorrow's Focus
            </Text>
            {report.tomorrowRecommendations.map((rec, i) => (
              <View key={i} style={{ flexDirection: "row", alignItems: "flex-start", marginBottom: 8 }}>
                <Text style={{ color: "#A78BFA", fontSize: 13, marginRight: 8, marginTop: 1 }}>{i + 1}.</Text>
                <Text style={{ color: "#CBD5E1", fontSize: 13, flex: 1, lineHeight: 20 }}>{rec}</Text>
              </View>
            ))}
          </View>

          {/* Sections Explored */}
          {report.tabsVisited.length > 0 && (
            <View style={{ backgroundColor: "#0C1A2E", borderRadius: 14, padding: 16, borderWidth: 1, borderColor: "rgba(34,211,238,0.1)", marginBottom: 20 }}>
              <Text style={{ color: "#64748B", fontSize: 11, fontWeight: "700", letterSpacing: 1.5, marginBottom: 10, textTransform: "uppercase" }}>
                🗺 Sections Explored
              </Text>
              <View style={{ flexDirection: "row", flexWrap: "wrap", gap: 8 }}>
                {report.tabsVisited.map((tab, i) => (
                  <View key={i} style={{
                    backgroundColor: "rgba(34,211,238,0.08)",
                    borderRadius: 20, paddingHorizontal: 12, paddingVertical: 5,
                    borderWidth: 1, borderColor: "rgba(34,211,238,0.2)",
                  }}>
                    <Text style={{ color: "#22D3EE", fontSize: 12 }}>{tab}</Text>
                  </View>
                ))}
              </View>
            </View>
          )}

          {/* Action Buttons */}
          <View style={{ gap: 10 }}>
            <Pressable
              onPress={() => onShare(report)}
              style={({ pressed }) => ({
                backgroundColor: pressed ? "#0E4A46" : "#0E6F69",
                borderRadius: 14, padding: 16, alignItems: "center",
              })}
            >
              <Text style={{ color: "#E8F4F0", fontSize: 15, fontWeight: "800" }}>📤  Share Report</Text>
            </Pressable>
            <Pressable
              onPress={onClose}
              style={({ pressed }) => ({
                backgroundColor: pressed ? "#1E2A3A" : "#0C1A2E",
                borderRadius: 14, padding: 14, alignItems: "center",
                borderWidth: 1, borderColor: "rgba(34,211,238,0.2)",
              })}
            >
              <Text style={{ color: "#64748B", fontSize: 14, fontWeight: "700" }}>Close</Text>
            </Pressable>
          </View>
        </ScrollView>
      </View>
    </Modal>
  );
}

