  async function handleEmergencyCall() {
    const callNumber = emergencyDialNumber.length > 0 ? emergencyDialNumber : defaultEmergencyNumber;
    const uri = `tel:${callNumber}`;

    try {
      const canOpen = await Linking.canOpenURL(uri).catch(() => true);
      if (canOpen) {
        await Linking.openURL(uri);
        return;
      }
    } catch {
      // Fall through to the alert below.
    }

    Alert.alert(
      "SOS call",
      `Your device could not open the phone app. Please dial ${callNumber} directly or use your local emergency service.`
    );
  }

  async function handleTrustedCall(contact: TrustedContact) {
    const phone = normalizePhoneNumber(contact.phone);
    if (!phone) return;

    const uri = `tel:${phone}`;
    try {
      const canOpen = await Linking.canOpenURL(uri).catch(() => true);
      if (canOpen) {
        await Linking.openURL(uri);
        return;
      }
    } catch {
      // Fall through to the alert below.
    }

    Alert.alert(
      "Call trusted contact",
      `Your device could not open the phone app. Please dial ${phone} for ${contact.name || "your contact"}.`
    );
  }

