  async function openWebsite(url: string, title: string) {
    if (!isTrustedExternalUrl(url)) {
      Alert.alert(
        "Link blocked",
        "This app only opens trusted help and official support domains."
      );
      return;
    }
    try {
      const canOpen = await Linking.canOpenURL(url).catch(() => true);
      if (canOpen) {
        await Linking.openURL(url);
        return;
      }
    } catch {
      // Fall through to the alert below.
    }

    Alert.alert(title, `Your device could not open ${url}.`);
  }

