    const todayEntries = entries.filter((e) => {
      const d = new Date(e.createdAt);
      const now = new Date();
      return d.getFullYear() === now.getFullYear() && d.getMonth() === now.getMonth() && d.getDate() === now.getDate();
    }).length;
    const topTones = [...new Set(entries.map((e) => e.toneLabel))].slice(0, 3).join(", ") || "None yet";
    const scoreHistory = entries.slice(0, 7).map((e) => e.score).join(", ");
