function isWithinDays(dateValue: string, days: number) {
  const time = new Date(dateValue).getTime();
  if (Number.isNaN(time)) return false;
  return Date.now() - time <= days * 24 * 60 * 60 * 1000;
}

function isToday(dateValue: string) {
  const date = new Date(dateValue);
  if (Number.isNaN(date.getTime())) return false;
  return date.toDateString() === new Date().toDateString();
}

function getDailyStreak(entries: CheckInEntry[]) {
  const days = new Set(entries.map((entry) => new Date(entry.createdAt).toDateString()));
  let streak = 0;
  const cursor = new Date();

  while (days.has(cursor.toDateString())) {
    streak += 1;
    cursor.setDate(cursor.getDate() - 1);
  }

  return streak;
}

function getSevenDayTrend(entries: CheckInEntry[]) {
  return Array.from({ length: 7 }).map((_, index) => {
    const date = new Date();
    date.setDate(date.getDate() - (6 - index));
    const dateKey = date.toDateString();
    const dayEntries = entries.filter((entry) => new Date(entry.createdAt).toDateString() === dateKey);
    const value =
      dayEntries.length === 0
        ? 0
        : Math.round(dayEntries.reduce((sum, entry) => sum + entry.score, 0) / dayEntries.length);

    return {
      key: dateKey,
      label: date.toLocaleDateString("en-US", { weekday: "short" }),
      value
    };
  });
}

function getThirtyDayTrend(entries: CheckInEntry[]) {
  return Array.from({ length: 30 }).map((_, index) => {
    const date = new Date();
    date.setDate(date.getDate() - (29 - index));
    const dateKey = date.toDateString();
    const dayEntries = entries.filter((entry) => new Date(entry.createdAt).toDateString() === dateKey);
    const value =
      dayEntries.length === 0
        ? 0
        : Math.round(dayEntries.reduce((sum, entry) => sum + entry.score, 0) / dayEntries.length);

    return {
      label: `${date.getDate()}`,
      value
    };
  });
}

function getTopRoutine(entries: CheckInEntry[]) {
  if (entries.length === 0) return "No pattern yet";
  const counts = entries.reduce<Record<string, number>>((acc, entry) => {
    acc[entry.routineName] = (acc[entry.routineName] ?? 0) + 1;
    return acc;
  }, {});
  return Object.entries(counts).sort((a, b) => b[1] - a[1])[0]?.[0] ?? "No pattern yet";
}

function getPatternRead(weeklyAverage: number) {
  if (weeklyAverage >= 76) return "Steady, but still watch complacency";
  if (weeklyAverage >= 58) return "Improving, but fragile";
  return "Too little signal to trust";
}

function getPatternCritique(
  weeklyAverage: number,
  monthlyAverage: number,
  topRoutine: string,
  weekCount: number,
  issueId: IssueId,
  identityId: IdentityId
) {
  const role = getPatternRoleFrame(identityId);
  const issueLabel =
    issueId === "general"
      ? "general guidance"
      : issueId === "anxiety"
        ? "anxiety"
        : issueId === "burnout"
          ? "burnout"
          : issueId === "loneliness"
            ? "loneliness"
            : issueId === "anger"
              ? "anger"
              : issueId === "overconfidence"
                ? "overconfidence"
                : issueId === "stigma"
                  ? "stigma"
                  : issueId === "fear"
                    ? "fear"
                    : issueId === "grief"
                      ? "grief"
                      : issueId === "trauma"
                        ? "trauma recovery"
                        : issueId === "addiction"
                          ? "addiction recovery"
                          : issueId === "health"
                            ? "health concern"
                            : issueId === "financial"
                              ? "financial stress"
                              : issueId === "relationship"
                                ? "relationship strain"
                                : issueId === "parenting"
                                  ? "parenting challenge"
                                  : issueId === "academic"
                                    ? "academic pressure"
                                    : issueId === "identity"
                                      ? "identity exploration"
                                      : "this issue";
  const issueNext =
    issueId === "general"
      ? "Test one clear route, one follow-up note, and one handoff before adding more detail."
      : issueId === "anxiety"
        ? "Test sleep, caffeine, and one breathing reset for seven days."
        : issueId === "burnout"
          ? "Test one lighter day, one boundary, and one real rest block."
          : issueId === "loneliness"
            ? "Test one human contact and one recovery habit each day."
            : issueId === "anger"
              ? "Test a pause before reply, a write-it-down step, and one cool-down routine."
              : issueId === "overconfidence"
                ? "Test one decision check, one feedback loop, and one slower response."
                : issueId === "stigma"
                  ? "Test one reality check, one kind self-statement, and one support contact."
                  : issueId === "fear"
                    ? "Test one small exposure, one breath reset, and one trusted check-in."
                    : issueId === "grief"
                      ? "Test one gentle connection, one memory held with kindness, and one small today-step."
                      : issueId === "trauma"
                        ? "Test one grounding practice, one safe person contact, and one very small daily anchor."
                        : issueId === "addiction"
                          ? "Test one craving-interrupt habit, one support contact check-in, and one urge journal entry."
                          : issueId === "health"
                            ? "Test one medical action, one symptom note, and one honest conversation with someone you trust."
                            : issueId === "financial"
                              ? "Test one expense note, one reduced-pressure decision, and one call or query about your options."
                              : issueId === "relationship"
                                ? "Test one regulated response, one boundary stated clearly, and one honest feeling written down."
                                : issueId === "parenting"
                                  ? "Test one act of self-care, one moment of full presence, and one honest conversation with your child."
                                  : issueId === "academic"
                                    ? "Test one study block with a timer, one honest review of what stuck, and one rest break that is actually restful."
                                    : issueId === "identity"
                                      ? "Test one authentic expression, one boundary against a role that does not fit, and one conversation with someone who knows you."
                                      : "Test one smaller plan, one note, and one calmer return tomorrow.";
  if (weekCount === 0) {
    return {
      title: "No evidence yet",
      summary: `This screen cannot honestly read a habit that has not been logged for a ${role.label.toLowerCase()} dealing with ${issueLabel}.`,
      warning: "Without check-ins, the chart is decoration, not insight.",
      next: `Use Home for three check-ins that fit this ${role.label.toLowerCase()} role, then return here for a real read. ${role.next}`,
    };
  }

  const gap = weeklyAverage - monthlyAverage;
  const dominantRoutine = topRoutine !== "No pattern yet" ? topRoutine : "your main routine";

  if (weeklyAverage >= 76) {
    return {
      title: "Strong, but narrow",
      summary: `${dominantRoutine} is carrying most of the pattern, which is useful but not enough by itself for ${role.label.toLowerCase()}.`,
      warning: "High scores can hide dependence on one routine and make the system brittle.",
      next: `Add one backup routine and one lower-effort day so the pattern can survive ${issueLabel}. ${role.next}`
    };
  }

  if (weeklyAverage >= 58) {
    return {
      title: "Growing, but still fragile",
      summary: `The pattern is improving, but ${dominantRoutine} is not yet stable enough to trust on hard days for ${role.label.toLowerCase()}.`,
      warning: gap >= 8
        ? "This week is ahead of the monthly rhythm, so the progress may be newer than it looks."
        : gap <= -8
          ? "This week slipped below the monthly rhythm, so something changed or the routine got crowded out."
          : "The data is moving, but it is still easy to overread a short streak.",
      next: `Keep one anchor routine, then test one small adjustment for a full week. ${issueNext} ${role.next}`
    };
  }

  return {
    title: "Under strain",
    summary: `The pattern says the load is higher than the current recovery loop can hold for ${role.label.toLowerCase()}.`,
    warning: "Do not use this chart to push harder; use it to simplify the day.",
    next: `Reduce the plan, save one note, and switch to Calm, Path, or Help before adding more. ${issueNext} ${role.next}`
  };
}

function getPracticeCritique(
  playPoints: number,
  playWins: number,
  playStepCount: number,
  featuredLabel: string,
  issueId: IssueId,
  identityId: IdentityId
) {
  const issueLabel =
    issueId === "general"
      ? "general guidance"
      : issueId === "anxiety"
        ? "anxiety"
        : issueId === "burnout"
          ? "burnout"
          : issueId === "loneliness"
            ? "loneliness"
            : issueId === "anger"
              ? "anger"
              : issueId === "overconfidence"
                ? "overconfidence"
                : issueId === "stigma"
                  ? "stigma"
                  : issueId === "fear"
                    ? "fear"
                    : issueId;
  const identityLabel = identityId;

  const priorityIds: PlayChallengeId[] =
    issueId === "general"
      ? ["focus", "reflect", "reset", "move", "connect"]
      : issueId === "anxiety" || issueId === "burnout" || issueId === "health"
      ? ["reset", "focus", "reflect", "move", "connect"]
      : issueId === "loneliness" || issueId === "grief" || issueId === "parenting"
        ? ["connect", "reset", "reflect", "move", "focus"]
        : issueId === "anger" || issueId === "overconfidence" || issueId === "stigma" || issueId === "fear"
          ? ["reflect", "reset", "focus", "move", "connect"]
          : issueId === "trauma"
            ? ["reset", "move", "connect", "reflect", "focus"]
            : issueId === "addiction"
              ? ["move", "connect", "reset", "reflect", "focus"]
              : issueId === "financial" || issueId === "academic"
                ? ["focus", "reset", "reflect", "connect", "move"]
                : issueId === "relationship"
                  ? ["reflect", "connect", "reset", "move", "focus"]
                  : issueId === "identity"
                    ? ["reflect", "move", "connect", "reset", "focus"]
                    : identityId === "student"
            ? ["focus", "reset", "reflect", "move", "connect"]
            : identityId === "teacher" || identityId === "professional"
              ? ["reset", "reflect", "focus", "move", "connect"]
              : identityId === "parent" || identityId === "caregiver"
                ? ["connect", "reset", "reflect", "move", "focus"]
                : identityId === "child"
                  ? ["move", "reset", "connect", "reflect", "focus"]
                  : identityId === "officer" || identityId === "official"
                    ? ["reset", "reflect", "focus", "move", "connect"]
                    : identityId === "retired"
                      ? ["reflect", "connect", "reset", "move", "focus"]
                      : ["reset", "focus", "reflect", "move", "connect"];

  if (playStepCount === 0) {
    return {
      title: "Too passive",
      summary: `Practice only works when one small action gets finished. Browsing the deck is not progress, especially for ${issueLabel}.`,
      warning: "If you keep opening cards without finishing one, the tab becomes a pleasant delay.",
      next: `Start with ${featuredLabel}, finish one card, then stop.`,
      priorityIds
    };
  }

  if (playWins === 0) {
    return {
      title: "Warm-up only",
      summary: `You have motion, but nothing is closed yet, so the system is still teaching itself for ${identityLabel}.`,
      warning: "Points without a finish are just intention wearing a badge.",
      next: `Choose the smallest card and claim the reward once it is actually done.`,
      priorityIds
    };
  }

  if (playWins === 1 && playStepCount < 6) {
    return {
      title: "Early momentum",
      summary: "The tab is helping, but the habit is still too new to call reliable.",
      warning: "Do not chase more cards; repetition beats volume here.",
      next: "Repeat the same two cards for a week before adding variety.",
      priorityIds
    };
  }

  if (playPoints >= 40) {
    return {
      title: "Working well",
      summary: "You have enough movement to call this a real practice loop.",
      warning: "Keep it honest by using it for recovery, not for performance or points alone.",
      next: "Keep one body reset and one focus card in rotation.",
      priorityIds
    };
  }

  return {
    title: "Useful, if kept small",
    summary: "The deck is doing its job as long as it stays short, repeatable, and easy to finish.",
    warning: "The moment this becomes a big game, it stops being practical.",
    next: "Use one card per day and return to Path or Help when the problem is bigger than a practice task.",
    priorityIds
  };
}

function getDefaultIssueForIdentity(identityId: IdentityId): IssueId {
  return "general";
}

function getDefaultRedressRouteForIdentity(identityId: IdentityId): RedressRouteId {
  if (identityId === "student" || identityId === "child" || identityId === "teacher") return "academic";
  if (identityId === "officer" || identityId === "official") return "public";
  if (identityId === "banker" || identityId === "engineer" || identityId === "professional") return "private";
  if (identityId === "parent" || identityId === "caregiver") return "public";
  if (identityId === "doctor" || identityId === "nurse") return "private";
  return "academic";
}

function getLaunchNeedMeta(needId: LaunchNeedId) {
  return launchNeeds.find((need) => need.id === needId) ?? launchNeeds[0];
}

function buildGuidedJournalNote(
  rawNote: string,
  tone: Tone,
  guide: IssueGuide,
  identity: (typeof identityProfiles)[number],
  routine: Routine,
  profileAddressLabel?: string
) {
  const addressLabel = profileAddressLabel?.trim().length ? profileAddressLabel.trim() : identity.label;
  const userLine =
    rawNote.length > 0 && rawNote !== defaultDraft
      ? rawNote
      : `I checked in as ${addressLabel} with ${tone.label.toLowerCase()} energy.`;

  return [
    userLine,
    `Practical: ${guide.action}`,
    `Emotional: ${guide.emotionalLens}`,
    `Psychological: ${guide.theoreticalLens}`,
    `Spiritual: ${guide.spiritualLens}`,
    `Cultural: ${guide.culturalLens}`,
    `Focus: ${routine.name} - ${routine.meta}`,
    `Next step: ${guide.steps[0]}`
  ].join("\n");
}

function getJournalInsight(
  latestEntry: CheckInEntry,
  entryCount: number,
  weeklyAverage: number,
  guide: IssueGuide
) {
  const scoreDirection =
    latestEntry.score >= 70
      ? "Your latest check-in has enough clarity to protect momentum."
      : latestEntry.score >= 45
        ? "Your latest check-in is asking for a smaller next step."
        : "Your latest check-in is asking for recovery before pressure.";

  return {
    title: `${entryCount} saved / weekly clarity ${weeklyAverage}`,
    detail: `${scoreDirection} Continue with ${guide.label}: ${guide.steps[0]}`
  };
}

function formatDate(dateValue: string) {
  const date = new Date(dateValue);
  if (Number.isNaN(date.getTime())) return "";
  return date.toLocaleDateString("en-US", { month: "short", day: "numeric" });
}

function formatDateTime(dateValue: string) {
  const date = new Date(dateValue);
  if (Number.isNaN(date.getTime())) return "";
  return date.toLocaleString("en-US", {
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit"
  });
}

function isReminderMode(value: string): value is ReminderMode {
  return value === "morning" || value === "midday" || value === "evening";
}

function isIdentityId(value: string): value is IdentityId {
  return (
    value === "student" ||
    value === "teacher" ||
    value === "doctor" ||
    value === "engineer" ||
    value === "banker" ||
    value === "lawyer" ||
    value === "nurse" ||
    value === "entrepreneur" ||
    value === "professional" ||
    value === "homemaker" ||
    value === "parent" ||
    value === "child" ||
    value === "officer" ||
    value === "official" ||
    value === "caregiver" ||
    value === "retired" ||
    value === "other"
  );
}

function isProfileGenderId(value: string): value is ProfileGenderId {
  return (
    value === "female" ||
    value === "male" ||
    value === "nonbinary" ||
    value === "prefer_not_to_say" ||
    value === "other"
  );
}

function hasMeaningfulProfileSelection(state: Partial<PersistedAppState>) {
  const hasIdentityChoice =
    typeof state.identityId === "string" && isIdentityId(state.identityId) && state.identityId !== "other";
  const hasRoleChoice =
    typeof state.profileRoleId === "string" &&
    isIdentityId(state.profileRoleId) &&
    state.profileRoleId !== "other";
  const hasProfileDetail =
    (typeof state.profileName === "string" && state.profileName.trim().length > 0) ||
    (typeof state.profilePhone === "string" && state.profilePhone.trim().length > 0) ||
    (typeof state.profileEmail === "string" && state.profileEmail.trim().length > 0) ||
    (typeof state.profileLocation === "string" && state.profileLocation.trim().length > 0) ||
    (typeof state.profileGender === "string" &&
      isProfileGenderId(state.profileGender) &&
      state.profileGender !== "prefer_not_to_say") ||
    (typeof state.accessRole === "string" && state.accessRole !== "guest");
  const hasTrustedContact =
    Array.isArray(state.trustedContacts) &&
    state.trustedContacts.some((contact) => normalizeTrustedContact(contact) !== null);

  return hasIdentityChoice || hasRoleChoice || hasProfileDetail || hasTrustedContact;
}

function getIdentityLabel(id: IdentityId) {
  return identityProfiles.find((profile) => profile.id === id)?.label ?? "Other";
}

function getProfileGenderLabel(gender: ProfileGenderId) {
  return genderOptions.find((option) => option.id === gender)?.label ?? "Prefer not to say";
}

function getHonorificPrefix(gender: ProfileGenderId, roleId?: IdentityId) {
  if (gender === "male") return "Sir";
  if (gender === "female") {
    if (roleId === "student" || roleId === "child") return "Miss";
    return "Madam";
  }
  return "";
}

function getRespectfulAddressLabel(
  name: string,
  gender: ProfileGenderId,
  roleId: IdentityId,
  fallback: string
) {
  const cleanedName = name.trim();
  const prefix = getHonorificPrefix(gender, roleId);
  if (cleanedName.length === 0) return fallback;
  return prefix.length > 0 ? `${prefix} ${cleanedName}` : cleanedName;
}

// ── GeminiInsightsCard ── personal pattern summary on the Patterns tab ─────────

function GeminiInsightsCard({
  apiBase,
  name,
  issueLabel,
  weekAvg,
  monthAvg,
  streakDays,
  entryCount,
  topTone,
  recentNotes,
  insightText,
  loading,
  onFetch,
}: {
  apiBase: string;
  name: string;
  issueLabel: string;
  weekAvg: number;
  monthAvg: number;
  streakDays: number;
  entryCount: number;
  topTone: string;
  recentNotes: string[];
  insightText: string | null;
  loading: boolean;
  onFetch: () => void;
}) {
  if (apiBase.length === 0) return null;
  if (entryCount === 0) return null;

  return (
    <View style={{
      marginHorizontal: 16, marginTop: 16, marginBottom: 4,
      backgroundColor: "#081828", borderRadius: 18,
      borderWidth: 1, borderColor: "#1A3A55",
      padding: 18, overflow: "hidden"
    }}>
      {/* Header */}
      <View style={{ flexDirection: "row", alignItems: "center", marginBottom: 12 }}>
        <Text style={{ fontSize: 18, marginRight: 10 }}>✦</Text>
        <View style={{ flex: 1 }}>
          <Text style={{ color: "#63DED0", fontSize: 11, fontWeight: "700", letterSpacing: 1.2, textTransform: "uppercase" }}>
            Personal Pattern Analysis
          </Text>
          <Text style={{ color: "#475569", fontSize: 11, marginTop: 1 }}>
            {entryCount} check-ins · {streakDays > 0 ? `${streakDays}-day streak` : "No active streak"}
          </Text>
        </View>
        <Text style={{ color: "#FCD34D", fontSize: 10, opacity: 0.7 }}>Beacon</Text>
      </View>

      {/* Content */}
      {loading ? (
        <View style={{ paddingVertical: 12 }}>
          <Text style={{ color: "#475569", fontSize: 13, fontStyle: "italic" }}>Reading your patterns…</Text>
        </View>
      ) : insightText ? (
        <Text style={{ color: "#CBD5E1", fontSize: 13, lineHeight: 21 }}>{insightText}</Text>
      ) : (
        <View>
          <Text style={{ color: "#64748B", fontSize: 13, lineHeight: 19, marginBottom: 14 }}>
            {entryCount >= 3
              ? `You have ${entryCount} check-ins to analyse. Get a personalised reading of your emotional patterns.`
              : `Add a few more check-ins and come back for your pattern reading.`}
          </Text>
          {entryCount >= 3 && (
            <Pressable
              onPress={onFetch}
              accessibilityRole="button"
              style={({ pressed }) => ({
                alignSelf: "flex-start",
                backgroundColor: pressed ? "#0E4A6A" : "#0F3D5E",
                borderRadius: 10,
                paddingHorizontal: 16,
                paddingVertical: 9,
                borderWidth: 1,
                borderColor: "#1A6080"
              })}
            >
              <Text style={{ color: "#63DED0", fontSize: 13, fontWeight: "700" }}>Generate my pattern reading →</Text>
            </Pressable>
          )}
        </View>
      )}
    </View>
  );
}

function getReminderBody(mode: ReminderMode, guide: IssueGuide, profileAddressLabel: string) {
  const timeLead =
    mode === "midday"
      ? "Midday check-in"
      : mode === "evening"
        ? "Evening check-in"
        : "Morning check-in";
  const issueLeadMap: Record<IssueId, string> = {
    general: "One clear route, one concrete step, one follow-up check.",
    anger: "One boundary, one pause, one calmer reply.",
    anxiety: "One breath, one fact, one small next step.",
    fear: "One tiny action, one reality check, one steady contact.",
    overconfidence: "One fact check, one review, one slower decision.",
    stigma: "One kind word to yourself, one small step, one safe space.",
    burnout: "One load to reduce, one rest to protect, one task to delay.",
    loneliness: "One human contact, one routine, one plan for later.",
    grief: "One memory to honour, one person to call, one day at a time.",
    identity: "One honest question, one journal entry, one step toward clarity.",
    health: "One piece of information, one question for your doctor, one calming action.",
    financial: "One number to face, one option to explore, one person to talk to.",
    relationship: "One honest conversation, one boundary, one step toward clarity.",
    parenting: "One moment of connection, one adjustment, one conversation with your child.",
    trauma: "One grounding practice, one trusted person, one professional contact.",
    academic: "One task broken down, one study block, one compassionate thought.",
    addiction: "One honest admission, one support resource, one day without.",
  };

  const addressLead = profileAddressLabel.trim().length > 0 ? `${profileAddressLabel}, ` : "";

  return `${addressLead}${timeLead}: ${guide.label}. ${issueLeadMap[guide.id]}`;
}

function getFollowUpReminderBody(
  weekNumber: number,
  totalWeeks: number,
  guide: IssueGuide,
  profileAddressLabel: string
) {
  const addressLead = profileAddressLabel.trim().length > 0 ? `${profileAddressLabel}, ` : "";
  return `${addressLead}Follow-up ${weekNumber}/${totalWeeks}: ${guide.label}. ${guide.followUp} Open ${guide.steps[0]}.`;
}

function buildReminderDate(daysFromNow: number, hour: number, minute: number) {
  const date = new Date();
  date.setDate(date.getDate() + daysFromNow);
  date.setHours(hour, minute, 0, 0);
  return date;
}

function normalizeEmergencyNumber(value: string) {
  return normalizePhoneNumber(value);
}

function normalizePhoneNumber(value: string) {
  return value.replace(/[^\d+]/g, "").trim();
}

function normalizeVerificationPhoneNumber(value: string) {
  const cleaned = normalizePhoneNumber(value);
  if (!cleaned) return "";
  if (cleaned.startsWith("+")) return cleaned;

  const digits = cleaned.replace(/\D/g, "");
  if (digits.length === 10) return `+91${digits}`;
  if (digits.length === 11 && digits.startsWith("0")) return `+91${digits.slice(1)}`;
  if (digits.length === 12 && digits.startsWith("91")) return `+${digits}`;
  if (digits.length >= 8 && digits.length <= 15) return `+${digits}`;
  return "";
}

function normalizeTrustedContact(value: unknown): TrustedContact | null {
  if (!value || typeof value !== "object") return null;
  const contact = value as Partial<TrustedContact>;
  return {
    id:
      typeof contact.id === "string" && contact.id.trim().length > 0
        ? contact.id
        : `trusted-${Date.now()}-${Math.floor(Math.random() * 10000)}`,
    name: typeof contact.name === "string" ? contact.name : "",
    relationship: typeof contact.relationship === "string" ? contact.relationship : "",
    phone: typeof contact.phone === "string" ? contact.phone : ""
  };
}

function normalizeIssueProgress(
  value: unknown
): Partial<Record<IssueId, [boolean, boolean, boolean]>> {
  if (!value || typeof value !== "object") return {};

  const raw = value as Partial<Record<IssueId, unknown>>;
  const result: Partial<Record<IssueId, [boolean, boolean, boolean]>> = {};
  (Object.keys(raw) as IssueId[]).forEach((issueId) => {
    const progress = raw[issueId];
    if (!Array.isArray(progress)) return;
    const next: [boolean, boolean, boolean] = [
      Boolean(progress[0]),
      Boolean(progress[1]),
      Boolean(progress[2])
    ];
    result[issueId] = next;
  });
  return result;
}

function normalizePlayProgress(
  value: unknown
): Partial<Record<PlayChallengeId, [boolean, boolean, boolean]>> {
  if (!value || typeof value !== "object") return {};

  const raw = value as Partial<Record<PlayChallengeId, unknown>>;
  const result: Partial<Record<PlayChallengeId, [boolean, boolean, boolean]>> = {};
  (Object.keys(raw) as PlayChallengeId[]).forEach((challengeId) => {
    if (!isPlayChallengeId(challengeId)) return;
    const progress = raw[challengeId];
    if (!Array.isArray(progress)) return;
    const next: [boolean, boolean, boolean] = [
      Boolean(progress[0]),
      Boolean(progress[1]),
      Boolean(progress[2])
    ];
    result[challengeId] = next;
  });
  return result;
}

function normalizePlayClaimed(value: unknown): Partial<Record<PlayChallengeId, boolean>> {
  if (!value || typeof value !== "object") return {};

  const raw = value as Partial<Record<PlayChallengeId, unknown>>;
  const result: Partial<Record<PlayChallengeId, boolean>> = {};
  (Object.keys(raw) as PlayChallengeId[]).forEach((challengeId) => {
    if (!isPlayChallengeId(challengeId)) return;
    result[challengeId] = Boolean(raw[challengeId]);
  });
  return result;
}

function normalizeCommunityMessages(value: unknown): CommunityMessage[] {
  if (!Array.isArray(value)) return communityMessagesSeed.slice();

  return value
    .map(normalizeCommunityMessage)
    .filter((message): message is CommunityMessage => message !== null)
    .slice(0, 60);
}

function mergeCommunityMessages(current: CommunityMessage[], incoming: CommunityMessage | CommunityMessage[]) {
  const incomingList = Array.isArray(incoming) ? incoming : [incoming];
  const byId = new Map<string, CommunityMessage>();
  [...incomingList, ...current].forEach((message) => {
    const normalized = normalizeCommunityMessage(message);
    if (normalized) byId.set(normalized.id, normalized);
  });
  return Array.from(byId.values())
    .sort((a, b) => Date.parse(b.createdAt) - Date.parse(a.createdAt))
    .slice(0, 60);
}

function normalizeCommunityMessage(value: unknown): CommunityMessage | null {
  if (!value || typeof value !== "object") return null;
  const message = value as Partial<CommunityMessage>;
  const text = typeof message.text === "string" ? message.text.trim() : "";
  if (!text || adultContentPattern.test(text)) return null;

  const role = message.role === "verified" || message.role === "moderator" ? message.role : "user";
  const author = typeof message.author === "string" && message.author.trim().length > 0 ? message.author.trim() : role === "user" ? "Community member" : "Verified contributor";
  const tag = typeof message.tag === "string" && message.tag.trim().length > 0 ? message.tag.trim() : role === "verified" ? "Verified" : "Community";
  const topic = typeof message.topic === "string" && message.topic.trim().length > 0 ? message.topic.trim() : "general";
  const clientId =
    typeof message.clientId === "string" && message.clientId.trim().length > 0
      ? message.clientId.trim()
      : undefined;

  return {
    id:
      typeof message.id === "string" && message.id.trim().length > 0
        ? message.id
        : `community-${Date.now()}-${Math.floor(Math.random() * 10000)}`,
    createdAt:
      typeof message.createdAt === "string" && message.createdAt.trim().length > 0
        ? message.createdAt
        : new Date().toISOString(),
    author,
    role,
    tag,
    text,
    topic,
    clientId
  };
}

function normalizeCommunityChatMessages(value: unknown): CommunityChatMessage[] {
  if (!Array.isArray(value)) return communityChatSeed.slice();

  return value
    .map(normalizeCommunityChatMessage)
    .filter((message): message is CommunityChatMessage => message !== null)
    .slice(0, 80);
}

function mergeCommunityChatMessages(
  current: CommunityChatMessage[],
  incoming: CommunityChatMessage | CommunityChatMessage[]
) {
  const incomingList = Array.isArray(incoming) ? incoming : [incoming];
  const byId = new Map<string, CommunityChatMessage>();
  [...incomingList, ...current].forEach((message) => {
    const normalized = normalizeCommunityChatMessage(message);
    if (normalized) byId.set(normalized.id, normalized);
  });
  return Array.from(byId.values())
    .sort((a, b) => Date.parse(b.createdAt) - Date.parse(a.createdAt))
    .slice(0, 80);
}

function normalizeCommunityChatMessage(value: unknown): CommunityChatMessage | null {
  if (!value || typeof value !== "object") return null;
  const message = value as Partial<CommunityChatMessage>;
  const text = typeof message.text === "string" ? message.text.trim() : "";
  if (!text || adultContentPattern.test(text)) return null;
  const role = message.role === "verified" || message.role === "moderator" ? message.role : "user";
  const persona =
    message.persona === "moderator" || message.persona === "mentor" || message.persona === "support"
      ? message.persona
      : "mentor";
  const author =
    typeof message.author === "string" && message.author.trim().length > 0
      ? message.author.trim()
      : role === "user"
        ? "You"
        : persona === "moderator"
          ? "Community Moderator"
          : "Verified Mentor";
  const clientId =
    typeof message.clientId === "string" && message.clientId.trim().length > 0
      ? message.clientId.trim()
      : undefined;

  return {
    id:
      typeof message.id === "string" && message.id.trim().length > 0
        ? message.id
        : `community-chat-${Date.now()}-${Math.floor(Math.random() * 10000)}`,
    createdAt:
      typeof message.createdAt === "string" && message.createdAt.trim().length > 0
        ? message.createdAt
        : new Date().toISOString(),
    author,
    role,
    text,
    persona,
    clientId
  };
}

function normalizePrivateSpaceThreads(value: unknown): PrivateSpaceThread[] {
  if (!Array.isArray(value)) return privateSpaceSeedThreads.slice();

  const normalized = value
    .map(normalizePrivateSpaceThread)
    .filter((thread): thread is PrivateSpaceThread => thread !== null)
    .slice(0, 20);

  return normalized.length > 0 ? normalized : privateSpaceSeedThreads.slice();
}

function normalizePrivateSpaceThread(value: unknown): PrivateSpaceThread | null {
  if (!value || typeof value !== "object") return null;
  const thread = value as Partial<PrivateSpaceThread>;
  const kind: PrivateSpaceKind = thread.kind === "dm" ? "dm" : "group";
  const title = typeof thread.title === "string" ? thread.title.trim().slice(0, 60) : "";
  const members = Array.isArray(thread.members)
    ? thread.members
        .map((member) => (typeof member === "string" ? member.trim().slice(0, 40) : ""))
        .filter((member) => member.length > 0)
        .slice(0, 8)
    : [];
  const messages = Array.isArray(thread.messages)
    ? thread.messages
        .map(normalizePrivateSpaceMessage)
        .filter((message): message is PrivateSpaceMessage => message !== null)
        .slice(0, 60)
    : [];
  const safeTitle = title.length > 0 ? title : kind === "dm" ? "Direct chat" : "Chat room";
  if (adultContentPattern.test(safeTitle) || maliciousThreatPattern.test(safeTitle)) return null;

  return {
    id:
      typeof thread.id === "string" && thread.id.trim().length > 0
        ? thread.id
        : `private-room-${Date.now()}-${Math.floor(Math.random() * 10000)}`,
    createdAt:
      typeof thread.createdAt === "string" && thread.createdAt.trim().length > 0
        ? thread.createdAt
        : new Date().toISOString(),
    updatedAt:
      typeof thread.updatedAt === "string" && thread.updatedAt.trim().length > 0
        ? thread.updatedAt
        : new Date().toISOString(),
    kind,
    title: safeTitle,
    members,
    messages
  };
}

function normalizePrivateSpaceMessage(value: unknown): PrivateSpaceMessage | null {
  if (!value || typeof value !== "object") return null;
  const message = value as Partial<PrivateSpaceMessage>;
  const text = typeof message.text === "string" ? message.text.trim() : "";
  if (!text || adultContentPattern.test(text) || maliciousThreatPattern.test(text)) return null;
  const role: PrivateSpaceMessageRole =
    message.role === "you" || message.role === "member" || message.role === "moderator"
      ? message.role
      : typeof message.author === "string" && message.author.trim().toLowerCase() === "you"
        ? "you"
        : "member";
  const author =
    typeof message.author === "string" && message.author.trim().length > 0
      ? message.author.trim().slice(0, 40)
      : role === "you"
        ? "You"
        : role === "moderator"
          ? "Verified Mentor"
          : "Member";

  return {
    id:
      typeof message.id === "string" && message.id.trim().length > 0
        ? message.id
        : `private-message-${Date.now()}-${Math.floor(Math.random() * 10000)}`,
    createdAt:
      typeof message.createdAt === "string" && message.createdAt.trim().length > 0
        ? message.createdAt
        : new Date().toISOString(),
    author,
    role,
    text
  };
}

function normalizeAIHelpMessages(value: unknown): AIHelpMessage[] {
  if (!Array.isArray(value)) return aiHelpSeed.slice();

  const normalized = value
    .map(normalizeAIHelpMessage)
    .filter((message): message is AIHelpMessage => message !== null)
    .slice(0, 50);

  return normalized.length > 0 ? normalized : aiHelpSeed.slice();
}

function normalizeAIHelpMessage(value: unknown): AIHelpMessage | null {
  if (!value || typeof value !== "object") return null;
  const message = value as Partial<AIHelpMessage>;
  let text = typeof message.text === "string" ? message.text.trim() : "";
  if (
    message.id === "ai-help-welcome" &&
    /Tell me what happened in one or two lines/i.test(text)
  ) {
    text = buildAIHelpSeedReply();
  }
  const seriousContext =
    /(abuse|assault|blackmail|complaint|harass|police|professor|ragging|redress|teacher|workplace)/i.test(
      text
    );
  if (!text || (adultContentPattern.test(text) && !seriousContext) || maliciousThreatPattern.test(text)) return null;
  const role = message.role === "user" ? "user" : "assistant";
  const route =
    message.route === "guide" ||
    message.route === "redress" ||
    message.route === "professional" ||
    message.route === "urgent" ||
    message.route === "general"
      ? message.route
      : "general";
  const author =
    typeof message.author === "string" && message.author.trim().length > 0
      ? message.author
          .trim()
          .replace(/^Gemini Help$/i, "Beacon Guide")
          .replace(/^Gemini Router$/i, "Beacon Guide")
          .replace(/^Aethon Help$/i, "Beacon Guide")
          .replace(/^Aethon Router$/i, "Beacon Guide")
      : role === "user"
        ? "You"
        : "Beacon Guide";

  return {
    id:
      typeof message.id === "string" && message.id.trim().length > 0
        ? message.id
        : `ai-help-${Date.now()}-${Math.floor(Math.random() * 10000)}`,
    createdAt:
      typeof message.createdAt === "string" && message.createdAt.trim().length > 0
        ? message.createdAt
        : new Date().toISOString(),
    author,
    role,
    text,
    route
  };
}

function normalizeUserReviews(value: unknown): UserReview[] {
  if (!Array.isArray(value)) return [];
  return value
    .map(normalizeUserReview)
    .filter((review): review is UserReview => review !== null)
    .slice(0, 50);
}

function normalizeUserReview(value: unknown): UserReview | null {
  if (!value || typeof value !== "object") return null;
  const review = value as Partial<UserReview>;
  const text = typeof review.text === "string" ? review.text.trim() : "";
  if (!text || adultContentPattern.test(text) || maliciousThreatPattern.test(text)) return null;
  const rating = typeof review.rating === "number" ? Math.min(5, Math.max(1, Math.round(review.rating))) : 5;
  const roleId = typeof review.roleId === "string" && isIdentityId(review.roleId) ? review.roleId : "other";

  return {
    id:
      typeof review.id === "string" && review.id.trim().length > 0
        ? review.id
        : `review-${Date.now()}-${Math.floor(Math.random() * 10000)}`,
    createdAt:
      typeof review.createdAt === "string" && review.createdAt.trim().length > 0
        ? review.createdAt
        : new Date().toISOString(),
    rating,
    text,
    contact: typeof review.contact === "string" ? review.contact.trim().slice(0, 120) : "",
    roleId,
    platform: typeof review.platform === "string" ? review.platform.trim().slice(0, 40) : "unknown"
  };
}

function normalizeCommunityReports(value: unknown): CommunityReport[] {
  if (!Array.isArray(value)) return [];
  return value
    .map(normalizeCommunityReport)
    .filter((report): report is CommunityReport => report !== null)
    .slice(0, 30);
}

function normalizeCommunityReport(value: unknown): CommunityReport | null {
  if (!value || typeof value !== "object") return null;
  const report = value as Partial<CommunityReport>;
  const target = report.target === "chat" || report.target === "feed" ? report.target : null;
  const reason =
    report.reason === "adult" ||
    report.reason === "harassment" ||
    report.reason === "spam" ||
    report.reason === "offtopic" ||
    report.reason === "other"
      ? report.reason
      : "other";
  if (!target) return null;
  return {
    id:
      typeof report.id === "string" && report.id.trim().length > 0
        ? report.id
        : `report-${Date.now()}-${Math.floor(Math.random() * 10000)}`,
    createdAt:
      typeof report.createdAt === "string" && report.createdAt.trim().length > 0
        ? report.createdAt
        : new Date().toISOString(),
    target,
    targetId: typeof report.targetId === "string" ? report.targetId : "",
    reason,
    snippet: typeof report.snippet === "string" ? report.snippet : ""
  };
}

